INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2025-v0-041', '9e74c06c9851432797871b6a1314b8af46c37329', 2025, 0, 41, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'Al finalizar el período de seguimiento en el estudio PREDIMET (“Primary Prevention of Cardiovascular Disease with a Mediterranean Diet”), el 3,8% de los individuos asignados a dieta mediterránea presentaron algún tipo de evento cardiovascular (infartos de miocardio, ictus o muertes de origen cardiovascular), frente al 4,4% de eventos ocurridos en el grupo control. ¿Cuál es el número necesario de pacientes a tratar (NNT) con dieta mediterránea para evitar un evento cardiovascular?:', '[{"position": 1, "text": "26"}, {"position": 2, "text": "60"}, {"position": 3, "text": "80"}, {"position": 4, "text": "167"}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-042', '739be937b1d2672328654908ae0456b748c4c01c', 2025, 0, 42, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'En evaluación económica de intervenciones sanitarias, un estudio que compare los costes alternativos de dos intervenciones frente a sus resultados de salud expresados en años ajustados por calidad o años de vida ajustados por discapacidad se denomina:', '[{"position": 1, "text": "Análisis coste-beneficio."}, {"position": 2, "text": "Análisis coste-efectividad."}, {"position": 3, "text": "Análisis coste-utilidad."}, {"position": 4, "text": "Análisis de minimización de costes."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-043', '81ee5facd6e3b9f4870d052b95bc4e335520161a', 2025, 0, 43, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'Señala la opción INCORRECTA respecto a la enfermedad meningocócica:', '[{"position": 1, "text": "El mecanismo de transmisión es por gotas."}, {"position": 2, "text": "Se dispone de vacunas efectivas únicamente para la prevención de 4 subtipos de meningococo."}, {"position": 3, "text": "La vacuna frente a meningococo tipo B está incluida en el calendario sistemático de inmunizaciones del Sistema Nacional de Salud."}, {"position": 4, "text": "Ante un contacto de riesgo con un paciente con meningitis meningocócica, la vacunación del contacto no debe ser la primera estrategia de profilaxis postexposición."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-044', 'c676334418d78a4087bd41b47a8d2c9afd1634b4', 2025, 0, 44, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'Se diagnostica de varicela a un niño de 8 años. Su madre está embarazada de 32 semanas y se le solicita una serología en la que se observan anticuerpos de tipo IgG frente a varicela por debajo de los niveles protectores y niega haber padecido la enfermedad en el pasado. ¿Cuál es la actitud recomendada con la gestante sabiendo que han pasado 3 días desde el inicio de la exposición?', '[{"position": 1, "text": "Administrar una dosis de la vacuna frente a varicela."}, {"position": 2, "text": "Forzar la terminación del embarazo para poder vacunarla."}, {"position": 3, "text": "Es tarde para plantear una estrategia de profilaxis post-exposición."}, {"position": 4, "text": "Administrar gammaglobulinas polivalentes o hiperinmunes."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-045', 'ecace75e7f6897a4f2502e89d34fe9a852de06f6', 2025, 0, 45, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'En un metaanálisis, el riesgo relativo estimado para la asociación causal entre el uso de mascarilla y la incidencia de SARS-CoV-2 fue de 0,47. ¿Cuál es la interpretación correcta de este resultado?:', '[{"position": 1, "text": "La incidencia de SARS-CoV-2 se reduce un 47% cuando la población usa mascarilla."}, {"position": 2, "text": "No usar mascarilla aumenta un 53% el riesgo de infección por SARS-CoV-2."}, {"position": 3, "text": "El uso de mascarilla podría evitar 47 de cada 100 casos de SARS-CoV-2 que se dan en personas que no la usan."}, {"position": 4, "text": "La incidencia de SARS-CoV-2 en la población que no usa mascarilla se reduciría un 53% si la utilizara."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-046', 'df31868e5cc954fdbbf82018666d0c1d1bb8ae96', 2025, 0, 46, false, false, 'Farmacología', NULL, 'Hombre de 79 años de edad con antecedentes de hipertensión arterial, hiperuricemia y artrosis que acude a urgencias por presentar posible reacción adversa farmacológica. No refiere antecedentes alergológicos de interés. Después de una excursión en barco sin protección solar presenta un cuadro cutáneo agudo facial, principalmente en párpados superiores e inferiores, consistentes en eritema y edema intenso bilateral. El paciente estaba realizando tratamiento médico de forma habitual con hidroclorotiazida 25 mg, ambdipino 5 mg, atorvastatina 10 mg y apixaban 5 mg. ¿Cuál de los cuatro fármacos descritos es más probable que sea el responsable de una posible reacción de fotosensibilidad?', '[{"position": 1, "text": "Hidroclorotiazida."}, {"position": 2, "text": "Amlodipino."}, {"position": 3, "text": "Atorvastatina."}, {"position": 4, "text": "Apixaban."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-047', 'fe948b078c86768ef08f8474a11fa58a7879ba68', 2025, 0, 47, false, false, 'Oncología', NULL, '¿Con cuál de estos fármacos administrados en monoterapia es necesario realizar un ecocardiograma antes de su inicio?:', '[{"position": 1, "text": "Trastuzumab."}, {"position": 2, "text": "Tamoxifeno."}, {"position": 3, "text": "Paclitaxel."}, {"position": 4, "text": "Docetaxel."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-048', '61bc10b33f8e3422ca0f59a1a15ac42758c2c06e', 2025, 0, 48, false, false, 'Anestesiología y Reanimación', NULL, 'La inducción de secuencia rápida en la anestesia general es:', '[{"position": 1, "text": "Método de inducción anestésica utilizado cuando existe riesgo de regurgitación gástrica y aspiración pulmonar."}, {"position": 2, "text": "Método de inducción anestésica realizado exclusivamente con halogenados."}, {"position": 3, "text": "Procedimiento anestésico que requiere la ventilación del paciente con presión positiva."}, {"position": 4, "text": "Método de inducción anestésica utilizado habitualmente para la realización del procedimiento quirúrgico programado."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-049', 'ab6ec51001edc358d1572fb378c85eba2f9a3790', 2025, 0, 49, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Señale la actitud correcta ante un paciente en edad infantil que refiere antecedente de traumatismo facial no tratado hace 3 años y que presenta limitación progresiva de la apertura oral y desviación del mentón hacia un lado:', '[{"position": 1, "text": "Debe descartarse la existencia de una fractura antigua tipo Lefort-1."}, {"position": 2, "text": "Debe realizarse un estudio mediante tomografía computarizada para descartar una displasia fibrosa."}, {"position": 3, "text": "Debe descartarse el diagnóstico de osteocondroma del cóndilo mandibular."}, {"position": 4, "text": "Debe descartarse el diagnóstico de anquilosis témporo-mandibular."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-050', 'aa7fdba57729b4c18e1b7669391dbcf8d20067fe', 2025, 0, 50, false, false, 'Cirugía Plástica', NULL, 'Respecto al colgajo DIEP (Deep inferior epigastric perforator), señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Se trata de un colgajo basado en vasos perforantes que puede ser usado como colgajo libre o como colgajo pediculado."}, {"position": 2, "text": "Está irrigado por ramas de la arteria circunfleja femoral lateral."}, {"position": 3, "text": "Puede utilizarse para reconstrucción manaria."}, {"position": 4, "text": "Los vasos perforantes musculocutáneos atraviesan el músculo recto del abdomen antes de irrigar la piel del colgajo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-051', '32134630b59d6d588e29e85a18e6cf42cadf7288', 2025, 0, 51, false, false, 'Cirugía Plástica', NULL, '¿Cuál de los siguientes escenarios podría suponer una contraindicación para el uso de un injerto de piel parcial como cobertura de un defecto cutáneo?:', '[{"position": 1, "text": "Cuando el defecto cutáneo abarca una gran superficie corporal."}, {"position": 2, "text": "En un paciente con comorbilidades médicas significativas."}, {"position": 3, "text": "Cuando hay un tendón sin prariención en la base de la herida."}, {"position": 4, "text": "Cuando hay una infección activa en el lecho de la herida."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-052', 'ad0faf568d4c4483a366be35f6ba1d5e100face1', 2025, 0, 52, false, false, 'Oftalmología', NULL, 'Un enfermo diabético de reciente diagnóstico acude a revisión oftalmológica. A las pocas horas vuelve con un cuadro bilateral de edema y eritema palpebral, quemosis, hiperemia conjuntival, lagrimeo y picor. Su actitud debe ser:', '[{"position": 1, "text": "Solicitar una analítica con glucemia, hemoglobina glicosilada y velocidad de sedimentación globular."}, {"position": 2, "text": "Prescribir un colirio antihistamínico o corticoide de baja potencia."}, {"position": 3, "text": "Realizar una OCT (tomografía de coherencia óptica) para descartar la existencia de un edema macular diabético."}, {"position": 4, "text": "Realizar una gonioscopia para descartar la presencia de neovasos en el ángulo camerular."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-053', '75bd6466d21bec55803e7c43e0766aaa61fb01c3', 2025, 0, 53, false, false, 'Oftalmología', NULL, 'En relación al tratamiento quirúrgico de las cataratas, señale cuál de los siguientes enunciados es correcto:', '[{"position": 1, "text": "El empeoramiento de la visión cercana está inducido por la catarata y se denomina miopía de índice."}, {"position": 2, "text": "La cirugía de cristalino disminuye el riesgo de desprendimiento de retina en los pacientes miopes jóvenes."}, {"position": 3, "text": "Las cataratas se operan cuando la agudeza visual está muy disminuida sin tener en cuenta otros síntomas o signos."}, {"position": 4, "text": "Los fármacos alfa bloqueantes como la tamsulosina asocian complicaciones intraoperatorias."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-054', '06a41d340f433e3b6c48e520bd8e4f0c1906739a', 2025, 0, 54, false, false, 'Oftalmología', NULL, 'Hombre de 72 años exfumador, acude a consulta por visión borrosa y dificultad para leer, especialmente en el ojo derecho, situación que ha progresado lentamente en los últimos seis meses. En la exploración del segmento anterior no se encuentran alteraciones clínicamente relevantes. En el ojo derecho se observan múltiples drusas en la región macular (una de tamaño grande) y alteraciones pigmentarias. En la tomografía de coherencia óptica se muestra un adelgazamiento del epitelio pigmentario de la retina y áreas de acumulación de material subretiniano en la mácula del ojo derecho. ¿Cuál es el manejo inicial indicado para este paciente?:', '[{"position": 1, "text": "Iniciar tratamiento con implante intravítreo de dexametasona."}, {"position": 2, "text": "Recomendar el uso de suplementos vitamínicos específicos."}, {"position": 3, "text": "Indicar de forma preferente cirugía de catarata con implante de lente intraocular."}, {"position": 4, "text": "Iniciar tratamiento con inyecciones intravítreas de anti-VEGF (factor de crecimiento endotelial vascular)."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-055', 'f144c7a97157325d92577104b7ec4e1ee157be63', 2025, 0, 55, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Hombre de 26 años que presenta otorrea unilateral derecha de una semana de evolución desde su regreso de vacaciones en la playa donde una ola le arrolló provocando inmersión. Refiere haber sido tratado en la infancia con colocación de drenajes transitimpánicos bilaterales y ha evitado la entrada de agua en los oídos desde entonces. No presenta dolor, pero sí molestias y leve hipoacusia. Tampoco tiene vértigo, pero sí sensación de taponamiento ótico. En la otoscopia se evidencia una perforación timpánica central de bordes lisos y otorrea que proviene de oído medio. ¿Cuáles son el diagnóstico y tratamiento del paciente?:', '[{"position": 1, "text": "Reactivación de una otitis media crónica simple que será tratada con ciprofloxacino en gotas óticas y remitir a Otorrinolaringología."}, {"position": 2, "text": "Otitis media aguda que precisa tratamiento con gentamicina en gotas óticas y revisión otoscópica pasada una semana."}, {"position": 3, "text": "Otitis media crónica colesteatomatosa que será tratada con gentamicina en gotas óticas y remitir a Otorrinolaringología."}, {"position": 4, "text": "Otitis externa aguda complicada que precisa tratamiento con ciprofloxacino en gotas óticas y revisión otoscópica pasada una semana."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-056', 'c2158d9275368ebd572c00a508cc0ee25ca2d6be', 2025, 0, 56, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Hombre de 40 años que acude a urgencias por presentar un cuadro de mareo con giro de objetos acompañado de náuseas, vómitos, palidez y sudoración de varias horas de evolución. Nunca había presentado un cuadro similar. No refiere hipoacusia ni acúfeno ni sensación de taponamiento. La otoscopia es normal. Se observa un nistagmo horizonto-rotatorio hacia el lado derecho grado III que aumenta la velocidad cuando dirige la mirada a la derecha, maniobra oculocefálica positiva izquierda, test de Skew y el test de Romberg positivo a la izquierda. ¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Infarto cerebral."}, {"position": 2, "text": "Neuritis vestibular."}, {"position": 3, "text": "Enfermedad de Menière."}, {"position": 4, "text": "Vértigo posicional paroxístico benigno."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-057', 'f8f1a2500e7f34a5af6282ecec0112b9bb25d2cc', 2025, 0, 57, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Mujer de 54 años consulta por hipoacusia unilateral derecha de horas de evolución que se ha presentado de manera brusca. Presentó un cuadro viral de vía aerodigestiva superior hace unos días. Sin antecedentes de interés, no presenta vértigo ni sensación de taponamiento ótico ni acúfeno. No refiere dolor ni presenta parálisis facial. La otoscopia es normal. En la acumetría la prueba Rinne es positiva bilateral y la pruebas Weber lateraliza al lado izquierdo. ¿Cuál es la sospecha diagnóstica y el manejo?:', '[{"position": 1, "text": "Hipoacusia súbita, se solicitará una tomografía computerizada craneal urgente."}, {"position": 2, "text": "Hipoacusia de conducción por otitis media serosa, se tratará con lavados nasales y esteroides tópicos nasales."}, {"position": 3, "text": "Hipoacusia súbita, precisa audiometría tonal urgente y se tratará con corticoterapia sistémica y/o intratimpánica."}, {"position": 4, "text": "Síndrome de Ramsay-Hunt se tratará con corticoterapia más valaciclovir."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-058', 'd817aee8a55972dbc149a4f2c6246193252e6bf9', 2025, 0, 58, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer que acude a ecografía de rutina de segundo trimestre a las 22 semanas de gestación. Las biometrías corresponden a un feto de 19 semanas. ¿Cuál es el siguiente paso para orientar el caso?:', '[{"position": 1, "text": "Valorar estudio genético teniendo en cuenta el riesgo de anomalía cromosómica en primer trimestre."}, {"position": 2, "text": "Valorar si la gestación está correctamente datada según la longitud craneocaudal fetal de la ecografía del primer trimestre."}, {"position": 3, "text": "Repetir ecografía para nuevas biometrías en 2 semanas."}, {"position": 4, "text": "Estudio para descartar preeclampsia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-059', '7ed61199521024c2db000f2033fd74719d534802', 2025, 0, 59, false, false, 'Ginecología y Obstetricia', NULL, '¿Cuál de los siguientes métodos anticonceptivos
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2025-v0-091', '858ecae74a4b867e129eefd19a76f0a9582fc1bd', 2025, 0, 91, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Mujer de 19 años que, practicando patinaje sobre ruedas, sufre un traumatismo indirecto de la rodilla derecha, con luxación de rótula tratada en urgencias. Acude a revisión 2 meses más tarde y refiere que nota dolor y sensación de inestabilidad y subluxación frecuente con la actividad física. De los siguientes elementos, señale el que NO favorece la inestabilidad fémoro-patelar:', '[{"position": 1, "text": "Anteversión femoral."}, {"position": 2, "text": "Torsión tibial interna."}, {"position": 3, "text": "Genu valgo."}, {"position": 4, "text": "Patela alta."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-092', '1dfe32480ad4bbb660c3385337afb9f8a1e8d5fe', 2025, 0, 92, false, false, 'Traumatología y Cirugía Ortopédica', NULL, '92. Desde el punto de vista fisiopatológico la osteonecrosis de la cabeza femoral se puede desencadenar por todos los mecanismos aquí descritos EXCEPTO:', '[{"position": 1, "text": "Anomalías en el flujo vascular por factores genéticos."}, {"position": 2, "text": "Oclusión intravascular por émbolos (lípidos, nitrógeno, hematíes anómalos)."}, {"position": 3, "text": "Debiscencia de la íntima arterial de los vasos."}, {"position": 4, "text": "Compresión extravascular a consecuencia de un acúmulo graso."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-093', '38067cf4c5201a6e0c1aaffa88ead19ccb62b51b', 2025, 0, 93, false, false, 'Reumatología', NULL, 'Mujer de 68 años con IMC 28 kg/m² que consulta por dolor crónico en rodilla derecha. Refiere que el dolor empeora con la actividad física, especialmente al subir y bajar escaleras, y mejora con el reposo. En la exploración física se observa crepitación en la rodilla derecha y leve deformidad en ambas. Una radiografía de rodilla derecha muestra estrechamiento del espacio articular y formación de osteofitos. ¿Cuál es la opción de tratamiento más adecuada en este caso?:', '[{"position": 1, "text": "Inmovilización de la rodilla con rodillera de descarga rotuliana."}, {"position": 2, "text": "Pérdida de peso y ejercicio físico supervisado para fortalecer el cuádriceps."}, {"position": 3, "text": "Infiltración intraarticular de corticoides."}, {"position": 4, "text": "Tratamiento farmacológico con tramadol."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-094', '9aa70497a9450e6134b5dd04bf54b806c22c0aec', 2025, 0, 94, false, false, 'Reumatología', NULL, 'Hombre de 30 años que acude a consulta por dolor lumbar crónico que empeora en la noche y mejora con el ejercicio. Refiere rigidez matutina de más de una hora. La exploración física revela una disminución de la movilidad en la columna lumbar y dolor a la palpación y exploración de las articulaciones sacrolíacas. La resonancia magnética muestra edema en las articulaciones sacrolíacas compatible con sacrolletis. ¿Cuál es el tratamiento inicial más indicado para este paciente?:', '[{"position": 1, "text": "Metotrexate subcutáneo semanal."}, {"position": 2, "text": "Corticoides orales."}, {"position": 3, "text": "Fisioterapia y antiinflamatorios no esteroides (AINEs)."}, {"position": 4, "text": "Terapia biológica con anti-TNF."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-095', 'd6737746a5aac3ce72c16166abed7389835e7bf7', 2025, 0, 95, false, false, 'Reumatología', NULL, 'Mujer de 83 años hospitalizada por neumonía adquirida en la comunidad por neumococo. Presenta una artritis aguda de carpo derecho. Sospechamos enfermedad por depósito de pirofosfato pero no se observa condrocalcinosis en la radiografía de carpos ni se ha conseguido obtener líquido sinovial durante la artrocentesis. ¿Qué radiografías añadiremos al cribado con el objetivo de identificar condrocalcinosis?:', '[{"position": 1, "text": "Radiografía anteroposterior de rodillas y de sínfisis de pubis."}, {"position": 2, "text": "Radiografía anteroposterior de rodillas y de hombros."}, {"position": 3, "text": "Radiografía anteroposterior de sínfisis de pubis y de hombros."}, {"position": 4, "text": "Radiografía anteroposterior de rodillas y de codos."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-096', 'd394d33e61a51cf1f5c9af0095a9177ff4863270', 2025, 0, 96, false, false, 'Reumatología', NULL, 'Uno de estos hallazgos anatomopatológicos sugiere el diagnóstico de enfermedad por IgG4:', '[{"position": 1, "text": "Trombosis arterial."}, {"position": 2, "text": "Proliferación de la íntima arterial sin datos de vasculitis."}, {"position": 3, "text": "Fibrosis estoriforme."}, {"position": 4, "text": "Infiltrado perivascular de polimorfonucleares."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-097', 'b1cad1f2cda59561eef016ad7b955b035bae3432', 2025, 0, 97, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, '¿Cuál de los siguientes hallazgos NO esperaría encontrar en una mujer de 28 años con una comunicación interauricular evolucionada?:', '[{"position": 1, "text": "Soplo mesosistólico."}, {"position": 2, "text": "Aumento de la silueta cardíaca en la radiografía de tórax."}, {"position": 3, "text": "Bloqueo de rama derecha en el electrocardiograma."}, {"position": 4, "text": "Hipertrofia del ventrículo izquierdo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-098', 'f0d5da921d65f02672f351cd787841c4fb1e3c48', 2025, 0, 98, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Joven de 16 años con astenia desde hace 1 mes, que durante un partido de fútbol sufre un síncope. A su llegada al hospital inconsciente y hemodinámicamente inestable presenta síntomas y signos de accidente cerebrovascular, de isquemia mesentérica y de isquemia arterial periférica, en miembro superior izquierdo y de ambos miembros inferiores. ¿Cuál cree que es el diagnóstico de sospecha?:', '[{"position": 1, "text": "Bloqueo aurículo-ventricular de 3º grado."}, {"position": 2, "text": "Insuficiencia mitral aguda."}, {"position": 3, "text": "Mixoma de aurícula izquierda."}, {"position": 4, "text": "Rotura de aneurisma de arteria cerebral media."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-099', 'fa7e36e433547da85ba19792d93f21fd6c194a7e', 2025, 0, 99, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 65 años, hipertenso desde hace 12 años, que acude por primera vez a la consulta de su médico de familia para una revisión rutinaria. La exploración física es normal y el electrocardiograma muestra ritmo sinusal a 68 lpm, con bloqueo de la rama izquierda del haz de His y duración del QRS de 150 ms. ¿Cuál de las siguientes situaciones implica este hallazgo?:', '[{"position": 1, "text": "Asincronía ventricular."}, {"position": 2, "text": "Miocardiopatía dilatada."}, {"position": 3, "text": "Disociación aurículo-ventricular."}, {"position": 4, "text": "Isquemia miocárdica aguda."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-100', '32292ce59877819623a76caacdbbde98b9724d7d', 2025, 0, 100, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Un entrenamiento aeróbico intenso y prolongado produce una serie de adaptaciones cardiovasculares que suelen denominarse "corazón de deportista". Entre las siguientes adaptaciones fisiológicas, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Bradicardia sinusal por aumento del tono vagal."}, {"position": 2, "text": "Bloqueo aurículo-ventricular de primer grado, de segundo grado Mobitz I e incluso de tercer grado durante el sueño."}, {"position": 3, "text": "Bloqueo completo de rama izquierda del haz de His por hipertrofia ventricular izquierda."}, {"position": 4, "text": "Bloqueo de rama derecha del haz de His por dilatación fisiológica ventricular derecha en deportes de resistencia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-101', '40499535ef3cc8401b1d446d24ce54687755005c', 2025, 0, 101, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, '¿Cuál de las siguientes complicaciones es más frecuente en el reemplazo valvular aórtico transcatéter (TAVI) respecto del reemplazo valvular quirúrgico?:', '[{"position": 1, "text": "Atelectasia pulmonar."}, {"position": 2, "text": "Bloqueo aurículo-ventricular completo."}, {"position": 3, "text": "Derrame pericárdico."}, {"position": 4, "text": "Hemorragia grave."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-102', 'ad53279ac3c0c774cb05af09adeed0607349d4b9', 2025, 0, 102, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Señale cuál de las siguientes situaciones se considera indicación de cirugía para el tratamiento de endocarditis infecciosa (EI):', '[{"position": 1, "text": "Aparición de insuficiencia renal aguda."}, {"position": 2, "text": "Hallazgo por imagen de émbolos esplénicos o renales en el momento del diagnóstico."}, {"position": 3, "text": "Presencia de vegetaciones mayores de 8 mm en válvula tricúspide en la EI derecha."}, {"position": 4, "text": "Hemocultivos positivos persistentes durante 7-10 días tras pauta antibiótica adecuada."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-103', '3c98c31dc399e7cfb97fe8c8deeb6873549ba873', 2025, 0, 103, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 68 años, hipertenso y fumador que acude a urgencias por dolor torácico y disnea desde hace 3 horas. Presenta mal estado general, presión arterial 118/45 mmHg, FC 105 lpm, saturación O2 96%. En la auscultación crepitantes basales finos, tonos cardíacos atenuados, que no permiten identificar soplos. Dímero D 16.000 ng/mL. El ECG muestra taquicardia sinusal y signos de hipertrofia ventricular izquierda. Un ecocardiograma urgente revela un ventrículo izquierdo hipertrófico, no dilatado, con disfunción sistólica global ligera, insuficiencia aórtica moderada, no conocida previamente y derrame pericárdico moderado-grave. Con estos datos, ¿qué patología debe descartar?:', '[{"position": 1, "text": "Disección de aorta proximal."}, {"position": 2, "text": "Infarto agudo de miocardio complicado con rotura de músculo papilar."}, {"position": 3, "text": "Tromboembolismo pulmonar masivo."}, {"position": 4, "text": "Pericarditis efusivo-constrictiva."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-104', '853defae4b56f6a3adebd84bbda7b307570a0abd', 2025, 0, 104, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 71 años portador de un marcapasos bicameral por bloqueo AV completo. Está en ritmo sinusal a 85 lpm con ritmo ventricular estimulado por el marcapasos. La interrogación del marcapasos muestra un porcentaje de estimulación ventricular del 99%. En el ecocardiograma tiene dilatación y disfunción sistólica de ambos ventrículos. La fracción de eyección del ventrículo izquierdo es del 30% y tiene insuficiencia mitral funcional grave. No tiene lesiones obstructivas en la coronariografía. Está en clase funcional III NYHA a pesar de tratamiento médico óptimo para la insuficiencia cardíaca con fracción de eyección reducida. ¿Cuál de las siguientes es la primera opción de tratamiento?:', '[{"position": 1, "text": "Cirugía de reparación valvular."}, {"position": 2, "text": "Cirugía de sustitución valvular."}, {"position": 3, "text": "Terapia de resincronización cardíaca."}, {"position": 4, "text": "Mitra-Clip."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-105', 'b4f535403603ecfdcd07e01ed25b4ea8087ffd6e', 2025, 0, 105, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Neonato de 10 días de vida que es traído por sus padres a los servicios de urgencias por presentar, desde hace 24 horas, rechazo de las tomas e hipotonía generalizada. Tras pruebas complementarias, se diagnostica de coartación de aorta productal crítica. El paciente evoluciona en pocas horas hacia el shock cardiogénico. En este contexto, ¿cuál debe ser el primer tratamiento para mejorar la hemodinámica de este paciente?', '[{"position": 1, "text": "Iniciar perfusión continua con prostaglandinas E1."}, {"position": 2, "text": "Administrar tratamiento con ibuprofeno."}, {"position": 3, "text": "Plantear cirugía de carácter emergente."}, {"position": 4, "text": "Realizar cateterismo y atriosepiostomía de Rashking urgente."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-106', '9a517e49af929ac379478a618fdbddf131c68b93', 2025, 0, 106, false, false, 'Cirugía General', NULL, 'Mujer de 46 años que tras 10 años de mastectomía derecha con vaciamiento ganglionar seguida de quimioterapia y radioterapia presenta linfedema de brazo derecho de larga evolución con importante edema y empastamiento, sin signos de celulitis. ¿Cuál de las siguientes medidas terapéuticas NO está recomendada?', '[{"position": 1, "text": "Realización de actividad física con elevación del miembro superior derecho."}, {"position": 2, "text": "Terapia física con fisioterapia descongestiva."}, {"position": 3, "text": "Diuréticos para reducir edema."}, {"position": 4, "text": "Liposucción."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-107', 'a544809b21eb9cc93970790df2a456c190541fc3', 2025, 0, 107, false, false, 'Angiología y Cirugía Vascular', NULL, 'En un paciente que tras una embolectomía por isquemia arterial aguda secundaria a un émbolo en la bifurcación aorto-ilíaca, presenta hipotensión, hipercalciuria, mioglobinuria e insuficiencia renal, ¿cuál de entre los siguientes es el diagnóstico más probable?', '[{"position": 1, "text": "Trombosis arterial recurrente."}, {"position": 2, "text": "Síndrome de reperfusión."}, {"position": 3, "text": "Necrosis muscular."}, {"position": 4, "text": "Neuropatía isquémica."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-108', '112d112ecea5810013cc21bbb36b54b1c1e8d83e', 2025, 0, 108, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 55 años con HTA y dislipemia que consulta por disnea de esfuerzo. Presenta en la ecocardiografía válvula aórtica bicúspide con área valvular aórtica de 0,9 cm2, gradiente transvalvular de 45 mmHg, velocidad pico de 5,5 m/seg, raíz aórtica de 6 cm y fracción de eyección de ventrículo izquierdo de 45%. En la analítica, péptido natriurético tipo B el triple de lo normal. ¿Qué opción terapéutica le recomendaría?:', '[{"position": 1, "text": "Seguimiento por médico de atención primaria mientras esté asintomático."}, {"position": 2, "text": "Implante de una prótesis valvular aórtica biológica transcatéter (TAVI)."}, {"position": 3, "text": "Valvuloplastia aórtica."}, {"position": 4, "text": "Cirugía de sustitución valvular aórtica y raíz."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-109', '85f09c2b15c34a45134b0f408f1d48effa89e7d2', 2025, 0, 109, false, false, 'Neumología y Cirugía Torácica', NULL, 'En la respuesta inmune innata, las células más numerosas a nivel pulmonar, que conforman la primera línea defensiva, son:', '[{"position": 1, "text": "Neutrófilos."}, {"position": 2, "text": "Macrófagos."}, {"position": 3, "text": "Eosinófilos."}, {"position": 4, "text": "Mastocitos."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-110', '9781ec9bd6281f0c85011e7dcfac9bfc6b726964', 2025, 0, 110, false, false, 'Neumología y Cirugía Torácica', NULL, 'Hombre de 60 años que acude a consulta por presentar tos y expectoración habitual mucosa, amarillenta, con más de 4-5 episodios de reagudizaciones al año, algunas veces con hemoptisis. ¿Cuál de los siguientes es el diagnóstico más probable?', '[{"position": 1, "text": "Asma."}, {"position": 2, "text": "Fibrosis pulmonar idiopática."}, {"position": 3, "text": "Bronquiectasias."}, {"position": 4, "text": "Insuficiencia cardíaca."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-111', '951bf5525f3b8c1e14c7536871487949094e53e9', 2025, 0, 111, false, false, 'Neumología y Cirugía Torácica', NULL, '¿Qué hallazgos de los descritos a continuación son MENOS probables en la exploración física de un paciente con fibrosis a nivel del intersticio pulmonar?:', '[{"position": 1, "text": "Sibilancias bilaterales en la auscultación pulmonar."}, {"position": 2, "text": "Crepitantes teleinspiratorios bibasales."}, {"position": 3, "text": "Disminución del murmullo vesicular con acropaquia."}, {"position": 4, "text": "Vibraciones vocales disminuidas con crepitantes tipo velcro, de carácter \"seco\"."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-112', '84182720ffd5f3794c0d67f763c325a9d2f62fdc', 2025, 0, 112, false, false, 'Neumología y Cirugía Torácica', NULL, 'Paciente que en revisión en consulta refiere tos matutina diaria y disnea de moderados esfuerzos (MRC 2) habitual que limita sus actividades cotidianas en tratamiento con doble terapia broncodilatadora desde hace dos años. La espirometría presenta un FEV1 del 35% del teórico en situación basal con una respuesta broncodilatadora que muestra un incremento del FEV1 de 250 mL y un 13%. En el estudio por TC se identifican áreas de enfisema centroacinar y en la analítica 250 eosinófilos/µL. En el último año ha sufrido dos exacerbaciones respiratorias de las cuales una ha requerido ingreso hospitalario. Indique el tratamiento más adecuado:', '[{"position": 1, "text": "Broncodilatador β-agonista de acción prolongada + broncodilatador antagonista muscarínico de acción prolongada + corticoide sistémico."}, {"position": 2, "text": "Añadir roflumilast a la terapia combinada."}, {"position": 3, "text": "Broncodilatador β-agonista de acción prolongada + broncodilatador antagonista muscarínico de acción prolongada + corticoide inhalado."}, {"position": 4, "text": "Broncodilatador β-agonista de acción prolongada + corticoide inhalado."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-113', 'd2b2affb9a40729ef2392f7cee7a92e13cd9c235', 2025, 0, 113, false, false, 'Neumología y Cirugía Torácica', NULL, 'Paciente con asma mal controlada a pesar de una combinación de glucocorticoides inhalados a dosis altas y un broncodilatador β-agonista de acción prolongada. Ha requerido ciclos de corticoides sistémicos sin una respuesta adecuada. Presenta rinosinusitis crónica con poliposis nasal y un recuento de eosinófilos de 400 células/µL en la analítica. Señale la respuesta correcta en cuanto al fenotipo asmático y la mejor opción de tratamiento.', '[{"position": 1, "text": "Se trata de un asma eosinofílica (T2) y una buena opción de tratamiento sería añadir omalizumab."}, {"position": 2, "text": "Se trata de un asma eosinofílica (T2) y una buena opción de tratamiento sería añadir mepolizumab."}, {"position": 3, "text": "Se trata de un asma no T2 y la mejor opción de tratamiento sería un antileucotrieno."}, {"position": 4, "text": "Se trata de un asma no T2 y la mejor opción de tratamiento sería añadir benzalizumab."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-114', 'ee8448a30b94ce1c0b97fa8d1c4931cfd62dd84f', 2025, 0, 114, false, false, 'Neumología y Cirugía Torácica', NULL, 'En el estudio de las enfermedades intersticiales difusas del pulmón, señale en que entidad el lavado broncoalveolar posee valor diagnóstico:', '[{"position": 1, "text": "Sarcoidosis."}, {"position": 2, "text": "Fibrosis pulmonar idiopática."}, {"position": 3, "text": "Neumonitis por hipersensibilidad."}, {"position": 4, "text": "Proteínosis alveolar."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-115', '779379779870a251f65e7af979adfad1dcdcc823', 2025, 0, 115, false, false, 'Neumología y Cirugía Torácica', NULL, 'Hombre de 65 años, exfumador, en el que de forma incidental se identifica un nódulo pulmonar solitario (NPS) en radiografía simple de tórax. Diagnosticado de enfermedad pulmonar obstructiva crónica con un FEV1 del 30%. En el estudio por TC se describe un NPS en lóbulo superior derecho de 9 mm de diámetro con cola pleural y calcificaciones excéntricas. Se realiza tomografía por emisión de positrones con captación patológica indicativa de malignidad. ¿Cuál de las siguientes actitudes terapéuticas es la más adecuada?:', '[{"position": 1, "text": "Es imprescindible la realización de una biopsia por cirugía torácica ante la elevada posibilidad de malignidad."}, {"position": 2, "text": "Al tratarse de un NPS de pequeño tamaño (< 1 cm) la actitud más adecuada es la de seguimiento radiológico estrecho con TC al mes y a los 3, 6 y 12 meses."}, {"position": 3, "text": "Ante la alta probabilidad de malignidad se recomienda realizar una prueba de esfuerzo cardiopulmonar y si el consumo máximo de oxígeno es <10 mL/kg/min remitir a cirugía torácica para resección.\n4.Se debe realizar una prueba de esfuerzo cardiopulmonar y si el consumo máximo de oxígeno es <10 mL/kg/min el manejo terapéutico más seguro es por medio de radioterapia estereotáxica fraccionada."}]'::jsonb, 3, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-116', 'd76c6cab0424a91a5f8e5771b85a34b415fcb5ae', 2025, 0, 116, false, false, 'Aparato Digestivo', NULL, 'En una mujer de 72 años con litiasis biliar asintomática se indicaría colecistectomía laparoscópica en caso de:', '[{"position": 1, "text": "Microlitiasis por alto riesgo de pancreatitis aguda."}, {"position": 2, "text": "Litiasis biliar de más de 2,5 cm de diámetro."}, {"position": 3, "text": "Vesícula con paredes calcificadas en porcelana."}, {"position": 4, "text": "Presencia de cálculos de bilirrubina."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-117', '6adb21a6eebe725eb8917b309c1c912d2dbad9e0', 2025, 0, 117, false, false, 'Cirugía General', NULL, '¿En cuál de las siguientes técnicas quirúrgicas para la reparación de una hernia inguinal NO se emplea una malla protésica?', '[{"position": 1, "text": "Shouldice."}, {"position": 2, "text": "Lichtenstein."}, {"position": 3, "text": "Reparación laparoscópica TEP (totalmente extraperitoneal)."}, {"position": 4, "text": "Reparación laparoscópica TAPP (transabdominal preperitoneal)."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-118', '34ee4dce0cd5bfec33bde94f9f77b9a11d3fdbf1', 2025, 0, 118, false, false, 'Aparato Digestivo', NULL, 'Mujer de 42 años que consulta por dolor rectal descrito como una sensación de peso u ocupación continua que se agrava con la deposición. En la exploración física el ano es normal y en el tacto rectal se palpa el músculo puborrectal hipertónico y doloroso a la tracción. ¿Cuál de los siguientes es el diagnóstico más probable?', '[{"position": 1, "text": "Úlcera solitaria de recto."}, {"position": 2, "text": "Proctalgia fugax."}, {"position": 3, "text": "Proctalgia inespecífica."}, {"position": 4, "text": "Síndrome del elevador del ano."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-119', '10597d9a40b74d6eb17bbd8a5b011cc5fe27f556', 2025, 0, 119, false, false, 'Oncología', NULL, 'Un hombre con diagnóstico de melanoma avanzado y en tratamiento con nivolumab (fármaco anti-PD-1) desarrolla elevación de las transaminasas siete veces los valores normales, junto con elevación de la bilirrubina total (2,3 mg/dL). Se han descartado cuadros infecciosos y no ha mejorado tras suspender el fármaco. ¿Cuál de las siguientes afirmaciones es cierta?', '[{"position": 1, "text": "Es una hepatitis inmunomediada por nivolumab y es indistinguible de una hepatitis autoinmune."}, {"position": 2, "text": "La reintroducción del fármaco una vez resuelta conlleva la reaparición del cuadro en la mayoría de los casos."}, {"position": 3, "text": "Los corticoides a dosis de 1 mg/kg de prednisona o equivalente son el tratamiento de elección en esta situación."}, {"position": 4, "text": "La aparición de esta entidad es tardía, generalmente meses después de iniciado el tratamiento."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-120', '41e9aeffda8a13f10cfd13fed6215c0d460a707f', 2025, 0, 120, false, false, 'Aparato Digestivo', NULL, 'Un paciente con enfermedad de Crohn con antecedente de extirpación de un melanoma precisa iniciar un tratamiento avanzado por corticodependencia. ¿Cuál de los siguientes fármacos se debería evitar al estar descrito un aumento del riesgo de dicha neoplasia?', '[{"position": 1, "text": "Azatioprina."}, {"position": 2, "text": "Infilximab."}, {"position": 3, "text": "Vedolizumab."}, {"position": 4, "text": "Ustekinumab."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-121', '97e88f5f01e4e258665eaefb57a044803b528774', 2025, 0, 121, false, false, 'Aparato Digestivo', NULL, 'Respecto al divertículo faringoesofágico o divertículo de Zenker, es cierto que:', '[{"position": 1, "text": "Es un divertículo por tracción y consta de todas las capas de la pared esofágica."}, {"position": 2, "text": "Es menos frecuente que los divertículos del tercio medio del esófago en la actualidad."}, {"position": 3, "text": "No se trata con mitotomía del cricofaríngeo si el tamaño es igual o menor a 2 cm."}, {"position": 4, "text": "Cuando se interviene mediante abordaje abierto para practicar una diverticulectomía o una divertículopexia, la incisión se realiza en el lado izquierdo del cuello."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-122', 'a2a48858475d9fdf4354104d67a016793a9b66f9', 2025, 0, 122, false, false, 'Aparato Digestivo', NULL, 'Hombre de 60 años con cirrosis hepática por VHC que acude a urgencias por hematemesis. A la exploración observamos ascitis y ligera ictericia. ¿Cuál es la actitud diagnóstica y terapéutica más adecuada?', '[{"position": 1, "text": "Estabilizar hemodinámicamente, hacer una endoscopia y colocar un TIPS si tiene hemorragia por varices."}, {"position": 2, "text": "Realizar una paracentesis, seguido de una endoscopia y ligadura de varices."}, {"position": 3, "text": "Estabilizar al paciente, iniciar un fármaco vasoactivo, realizar una endoscopia y practicar una ligadura si hay hemorragia por varices."}, {"position": 4, "text": "Esperar al resultado de la endoscopia para actuar en consecuencia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-123', '979d79fb26ccccb9b8e35cedb275064f04cf80cd', 2025, 0, 123, false, false, 'Endocrinología', NULL, 'Mujer de 38 años que presenta nódulo tiroideo indoloro y creciente en el lóbulo derecho de 6 meses de evolución. Ha experimentado recientemente disfagia y cambios de la voz. Se diagnostica de carcinoma medular de tiroides en estadio III con extensión extratiroidea y compromiso de ganglios linfáticos cervicales. De entre los siguientes, ¿cuál es el tratamiento más adecuado?:', '[{"position": 1, "text": "Tiroidectomía subtotal."}, {"position": 2, "text": "Hemitiroidectomía derecha."}, {"position": 3, "text": "Tiroidectomía total con extirpación de ganglios linfáticos cervicales."}, {"position": 4, "text": "Quimioterapia exclusiva."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-124', 'c0face0e2a6b3c26641dd379f36acf26b262504f', 2025, 0, 124, false, false, 'Aparato Digestivo', NULL, 'Mujer de 58 años que consulta por presentar desde hace varios meses dolor abdominal epigástrico intermitente, náuseas y pérdida de peso involuntaria de 8 kg. Refiere episodios ocasionales de vómitos biliosos, sin haber notado sangre en los vómitos ni en las heces. Ha estado tomando antiácidos sin mucho alivio. En la exploración física se aprecia abdomen blando, con dolor a la palpación profunda en el epigastrio, sin masas palpables ni signos de peritonitis. Los análisis muestran anemia microcítica e hipocrómica y ferropenia. En la gastroscopia lesión ulcerada en la segunda porción del duodeno, que se biopsia. El informe histológico confirma la presencia de adenocarcinoma duodenal. Una TC abdominal muestra la lesión limitada al duodeno, sin evidencia de diseminación a ganglios linfáticos o metástasis a distancia. ¿Cuál es el siguiente paso más adecuado en el manejo de esta paciente?', '[{"position": 1, "text": "Observación y seguimiento periódico con endoscopia digestiva alta debido a la localización del tumor."}, {"position": 2, "text": "Quimioterapia neoadyuvante seguida de una nueva evaluación para posible resección quirúrgica."}, {"position": 3, "text": "Duodenopancreatectomía cefálica (procedimiento de Whipple) como tratamiento de elección."}, {"position": 4, "text": "Radioterapia dirigida al duodeno para controlar la enfermedad local antes de considerar la cirugía."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-125', '7e4a2d9508425168c4ae4d5783d7010c05ee81ad', 2025, 0, 125, false, false, 'Cirugía General', NULL, 'Hombre de 70 años con antecedentes de hernia inguinal derecha no intervenida, que acude a urgencias por aparición de una tumoración en la zona inguino-crural derecha no reductible y muy dolorosa. Acude a urgencias con un cuadro de vómitos con dolor y distensión abdominal. ¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Hernia inguinal directa."}, {"position": 2, "text": "Hernia inguinal indirecta."}, {"position": 3, "text": "Hernia obturatriz."}, {"position": 4, "text": "Hernia crural."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-126', 'd4cada23a1dc3fddf8e9c38744458bde60b365d2', 2025, 0, 126, false, false, 'Aparato Digestivo', NULL, 'Hombre de 77 años que acude a urgencias por prurito, ictericia y síndrome tóxico de un mes de evolución. Refiere ingesta de amoxicilina-clavulánico desde hace 10 días por un resfriado. A su llegada se realiza una ecografía que se informa de dilatación de la vía biliar intra y extrahepática con vesícula biliar distendida. ¿Cuál es la sospecha diagnóstica y la actitud a seguir?:', '[{"position": 1, "text": "Colecistitis aguda e indicación de colecistectomía urgente."}, {"position": 2, "text": "Coledocolitiasis distal y solicitud de colangiorresonancia magnética."}, {"position": 3, "text": "Toxicidad por fármacos y suspensión de la medicación."}, {"position": 4, "text": "Tumoración maligna obstructiva de colédoco distal y solicitar TC abdominal."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-127', 'fa266a1903431a11793027753f8813eb65076222', 2025, 0, 127, false, false, 'Aparato Digestivo', NULL, 'La forma más eficaz de evaluación preoperatoria de la función del cuerpo esofágico y del esfínter esofágico inferior en un paciente con sospecha de reflujo gastroesofágico es:', '[{"position": 1, "text": "La monitorización ambulatoria del pH y la impedancia."}, {"position": 2, "text": "Manometría esofágica."}, {"position": 3, "text": "Esofagoduodenoscopia."}, {"position": 4, "text": "Esofagograma con bario."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-128', '10bd87088fc10c817a6ae02587b0706d929624c2', 2025, 0, 128, false, false, 'Cirugía General', NULL, 'Mujer de 34 años con diagnóstico de púrpura trombocitopénica idiopática (PTI) refractaria al tratamiento médico remitida para evaluación quirúrgica. A pesar del tratamiento con corticosteroides y otros inmunosupresores, sus recuentos plaquetarios han permanecido bajos, con episodios recurrentes de sangrado leve. Se decide realizar una esplenectomía laparoscópica como siguiente paso terapéutico. En relación con la planificación y manejo de la esplenectomía laparoscópica, ¿cuál de las siguientes estrategias es la más adecuada?:', '[{"position": 1, "text": "La ligadura temprana de la arteria esplénica es crucial para reducir el riesgo de sangrado intraoperatorio y debe realizarse antes de movilizar el bazo en todos los casos."}, {"position": 2, "text": "La preservación del polo inferior del bazo es recomendable en pacientes con PTI para mantener una función inmunológica parcial."}, {"position": 3, "text": "El abordaje lateral izquierdo es la única opción en esplenectomías laparoscópicas y debe emplearse independientemente del tamaño del bazo."}, {"position": 4, "text": "La vacunación preoperatoria contra neumococo, meningococo y Haemophilus influenzae es esencial para reducir el riesgo de infección postesplenectomía y debe completarse al menos dos semanas antes de la cirugía, siempre que sea posible."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-129', '4c05adaae812d432ead2d18ed6e6f81fe45cacc8', 2025, 0, 129, false, false, 'Cirugía General', NULL, '¿Cuál de las siguientes medidas aconsejadas para reducir la infección de la herida quirúrgica es INCORRECTA?:', '[{"position": 1, "text": "En caso de ser necesario eliminar el vello, está indicado rasurarlo con cortadora eléctrica o con cuchilla."}, {"position": 2, "text": "Es recomendable mantener la temperatura corporal del paciente >35,5ºC."}, {"position": 3, "text": "Es recomendable mantener la glucemia en cifras <180 mg/dL."}, {"position": 4, "text": "El intervalo de inicio de la infusión del antibiótico hasta la realización de la incisión debe ser menor de 60 minutos."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-130', 'b682015a4b5ec4ccebc5081e3c70bb33ad04a4d4', 2025, 0, 130, false, false, 'Nefrología', NULL, 'En un paciente diagnosticado de fracaso renal agudo, el tratamiento con hemodiálisis está indicado en todas las siguientes situaciones clínicas, EXCEPTO en una:', '[{"position": 1, "text": "Acidosis metabólica que no responde a tratamiento con bicarbonato."}, {"position": 2, "text": "Sobrecarga de volumen con edema agudo de pulmón."}, {"position": 3, "text": "Hiperpotasemia refractaria a tratamiento médico."}, {"position": 4, "text": "Proteinuria de 1 gramo en la orina de 24 horas."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-131', 'a5e4364a47d022b7311daf8fe9356ddb6a511786', 2025, 0, 131, false, false, 'Nefrología', NULL, 'Mujer de 54 años diagnosticada de diabetes mellitus tipo 2 hace tres años en tratamiento con metformina y lisinopril con buen control metabólico. Es enviada a consulta de Nefrología por creatinina sérica de 1,7 mg/dL, filtrado glomerular estimado de 49 mL/min/1,73m2 y cociente albumina/creatinina en orina de 250 mg/g. En los siguientes meses se confirma estabilidad de la función renal, las cifras de presión arterial se mantienen alrededor de 125/70 mmHg, en la ecografía se observan riñones de tamaño y morfología normal y en el estudio de fondo de ojo se objetiva una retinopatía diabética grado 2. ¿Cuál de las siguientes es la actitud a seguir?:', '[{"position": 1, "text": "No hacer modificaciones en el tratamiento dada la estabilidad y buen control de su enfermedad."}, {"position": 2, "text": "Añadir un antagonista del receptor de la angiotensina II para lograr un mejor control de la presión arterial y disminuir la albuminuria."}, {"position": 3, "text": "Indicar la realización de una biopsia renal para confirmar la existencia de una enfermedad renal diabética."}, {"position": 4, "text": "Iniciar tratamiento con un inhibidor del cotransportador de sodio-glucosa tipo 2 que promueve la excreción urinaria de glucosa y tiene un efecto nefroprotector."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-132', 'cc70997d08e8d4d361236ffc0befe84c140ab243', 2025, 0, 132, false, false, 'Nefrología', NULL, 'El síndrome de secreción inadecuada de hormona antidiurética (SIADH), se caracteriza por:', '[{"position": 1, "text": "Hiponatremia con osmolalidad sérica baja y osmolalidad urinaria elevada."}, {"position": 2, "text": "Hiponatremia hipovolémica con concentración urinaria de sodio y osmolalidad en orina elevadas."}, {"position": 3, "text": "Su tratamiento se basa en la restricción hídrica y la administración de fármacos agonistas del receptor de vasopresina."}, {"position": 4, "text": "En la mayoría de los casos se asocia con la administración de fármacos, especialmente antibióticos e inmunosupresores."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-133', '4a4637e4e3dc9306972a9912fdb9f65894f22343', 2025, 0, 133, false, false, 'Nefrología', NULL, 'Hombre de 37 años que se deriva a consulta de Nefrología para estudio de hematuria microscópica persistente. La exploración es normal salvo por presión arterial 160/100 mmHg. Hemograma sin alteraciones, urea 25 mg/dL, creatinina 0,8 mg/dL, Na 139 mEq/L, K 4,5 mEq/L, perfil hepático y lipídico normales, no hipoalbuminemia ni hipoproteinemia; estudio de autoinmunidad normal, complemento, inmunoglobulinas y proteinograma normales; serología vírica negativa; proteinuria de 0,75 g/24h; sedimento urinario con 30 eritrocitos por campo, 90% dismórficos, no leucocituria. Se realiza biopsia renal que muestra depósitos mesangiales de IgA, IgG y C3 con hipercelularidad mesangial (M1) y glomerulosclerosis segmentaria (S1) pero sin proliferación endocapilar (E0) ni fibrosis túbulo-intersticial (T0) ni presencia de semilunas. ¿En este momento, cuál de entre los siguientes es el tratamiento más recomendado?:', '[{"position": 1, "text": "Monoterapia con corticoides a 0,5 mg/kg/día con pauta descendente en 3 meses."}, {"position": 2, "text": "Control de la presión arterial y la proteinuria (añadir un antagonista de los receptores de angiotensina II)."}, {"position": 3, "text": "Rituximab como primera opción y, si no hay respuesta, administrar ciclofosfamida."}, {"position": 4, "text": "Corticoides a altas dosis junto con ciclofosfamida como tratamiento de inducción."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-134', '978bc5c222019b85e6690059447bba01a33d0172', 2025, 0, 134, false, false, 'Nefrología', NULL, 'Hombre de 65 años que presenta un episodio de infección respiratoria y es tratado con amoxicilina/clavulánico. Una semana después comienza con fiebre y aparición de rash cutáneo por lo que acude a Urgencias. En la analítica se objetiva deterioro de función renal con creatinina sérica 3,2 mg/dL (previa 1,2 mg/dL), eosinofilia y presencia de proteinuria y microhematuria en el sistemático de orina. Indique cuál de estas actitudes es la más correcta:', '[{"position": 1, "text": "Es necesario realizar una biopsia cutánea para establecer el diagnóstico.\n2.Hay que aumentar la dosis de antibiótico pues probablemente se trate de una nefropatía tubulointersticial aguda de etiología infecciosa."}, {"position": 3, "text": "Se debe suspender el antibiótico y plantear tratamiento con esteroides si la función renal no mejora en 2-3 días."}, {"position": 4, "text": "Hay que iniciar tratamiento con bolus de esteroides a dosis altas y realizar una biopsia renal."}]'::jsonb, 3, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-135', '0f59cd2f4de346526f6d694bb3e7b569fdb84729', 2025, 0, 135, false, false, 'Urología', NULL, 'Hombre de 72 años, remitido a consulta tras un hallazgo en una TC solicitada para el estudio de molestias digestivas inespecíficas. Se objetiva una lesión sólida, exofítica, heterogénea, con realce intenso tras la administración de contraste, de 4,9 cm de diámetro, dependiente del polo inferior renal derecho; en el riñón izquierdo litiasis plélica de 3 cm que condiciona hidronefrosis y atrofia cortical. Antecedentes personales de hipertensión, sobrepeso (mide 1,6 m y pesa 95 kg) y fumador habitual. En la analítica destaca creatinina sérica de 1,5 mg/dL. Señale de entre las siguientes opciones de tratamiento la que considera más adecuada:', '[{"position": 1, "text": "Nefrectomía bilateral, con suprarrenalectomía derecha y linfadenectomía retroperitoneal."}, {"position": 2, "text": "Nefrectomía parcial derecha."}, {"position": 3, "text": "Biopsia percutánea. Quimioterapia neoadyuvante y nefrectomía radical derecha."}, {"position": 4, "text": "Nefrectomía radical derecha. Inmunoterapia adyuvante."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-136', 'cad825232e95ed488bae4bd15e2edb8364c21aa2', 2025, 0, 136, false, false, 'Urología', NULL, 'Hombre de 53 años acude a urgencias por anuria de 48 horas de evolución. Presenta dolor abdominal difuso de varios días de evolución que no se modifica con la posición ni con la ingesta. No ha presentado fiebre pero sí náuseas con dos vómitos escasos biliosos sin productos patológicos, además de estreñimiento. En la analítica sanguínea presenta ligera leucocitosis con desviación izquierda, creatinina 7 mg/dL con FG<15mL/min, sodio 132 mmol/L y potasio 5,7 mmol/L, bilirrubina 1 mg/dL, amilasa 100 U/L, AST 30 U/L, ALT 45 U/L, fosfatasa alcalina 60 U/L, y GGT 70 U/L. En el sedimento de orina únicamente se evidencian 5-10 hematíes/campo y leve pluria. En la ecografía abdominal dilatación pielocalicial y ureteral moderada-severa bilateral con leve disminución del parénquima en el riñón izquierdo y múltiples imágenes hiperecoicas con sombra acústica posterior en todos los grupos caliciales así como en el uréter proximal izquierdo. ¿Cuál es la actitud más correcta a seguir?:', '[{"position": 1, "text": "Analgesia iv y sucroterapia intensiva para forzar diuresis."}, {"position": 2, "text": "Diuréticos intravenosos."}, {"position": 3, "text": "Derivación de la vía urinaria de forma bilateral."}, {"position": 4, "text": "Solicitar TC ante la sospecha de abdomen agudo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-137', '010063b3519429c76d0fd6da93bf79c8cecb06ad', 2025, 0, 137, false, false, 'Urología', NULL, 'Hombre de 28 años que consulta por haberse despertado por dolor en la región genital y tumefacción en el pene. No recuerda con detalle lo sucedido en las últimas 12 horas. En las últimas 48 h ha consumido alto volumen de alcohol, varias drogas (mefedrona, cocaína, anfetamina), junto con sildenafilo y se ha autoinyectado en el pene 20 µg de alprostadil. A la exploración destaca, pene flácido, glande no visible en su totalidad por edema y hematoma expansivo de partes blandas. Presenta restos hemáticos en el meato uretral. ¿Cuál de las siguientes opciones NO formaría parte de su plan terapéutico?:', '[{"position": 1, "text": "Gasometría obtenida mediante punción del cuerpo cavernoso."}, {"position": 2, "text": "Revisión quirúrgica urgente."}, {"position": 3, "text": "Evitar el sondaje vesical."}, {"position": 4, "text": "Ecografía de pene."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-138', '78777fa5f5577b35e3286920048b0028decd7102', 2025, 0, 138, false, false, 'Urología', NULL, 'Hombre de 51 años que consulta preocupado por la aparición de leve goteo postmiccional. Tiene dislipemia, hipertensión arterial y alopecia androgénica incipiente. Sigue tratamiento con sinvastatina, enalapril, minoxidil y dutasteride. Padre y hermano fallecidos por cáncer de próstata. En los reconocimientos de salud laboral realizados en 2.021 y 2.023 se observa PSA de 0,3 y de 3,8 ng/mL respectivamente (valores de referencia <4 ng/mL). Una RMN prostática multiparamétrica muestra una próstata de 55 mL y en secuencia T2 un nódulo hipointenso moderado y homogéneo de 1,7 cm, con restricción de la difusión y realce precoz en perfusión en el límite entre el estroma fibromuscular anterior y la zona transicional del lóbulo izquierdo prostático. Repetimos una nueva determinación de PSA 3,5 ng/mL. A la vista de estos hallazgos, ¿qué recomendación propondría al paciente como la más adecuada?:', '[{"position": 1, "text": "Biopsia prostática transrectal sistemática."}, {"position": 2, "text": "Iniciar un tratamiento antibiótico empírico durante 10 días y realizar una biopsia prostática sistemática al finalizar."}, {"position": 3, "text": "Tranquilizar al paciente, ofrecer tratamiento sintomático alfa-bloqueante y seguimiento."}, {"position": 4, "text": "Biopsia prostática transperineal sistemática y dirigida mediante fusión de imágenes RMN."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-139', '88f31f1729a463f3a69c3b194c792c6972239ec1', 2025, 0, 139, false, false, 'Oncología', NULL, '¿Cuál de estas afirmaciones es cierta sobre los subtipos moleculares de cáncer de mama?:', '[{"position": 1, "text": "El cáncer de mama triple negativo es el subtipo más frecuente."}, {"position": 2, "text": "El cáncer de mama HER2+ es el subtipo menos agresivo."}, {"position": 3, "text": "El cáncer de mama luminal A es el subtipo más raro."}, {"position": 4, "text": "El cáncer de mama triple negativo es el subtipo más agresivo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-140', 'ee4c4a73ff5f95fe9ebe1d568e8538e1a0e541d3', 2025, 0, 140, false, false, 'Oncología', NULL, 'Mujer de 60 años con diagnóstico reciente de cáncer de mama metastásico con alta carga tumoral. Acude a Urgencias 48 horas después de haber recibido el primer ciclo de tratamiento, con cuadro de náuseas, vómitos, diarrea, dolor abdominal, astenia intensa y letargia. En la analítica sanguínea presenta alteración de la función renal. ¿Cuál de las siguientes alteraciones analíticas esperaría encontrar también?:', '[{"position": 1, "text": "Hipouricemia."}, {"position": 2, "text": "Hiperpotasemia."}, {"position": 3, "text": "Hipofosfatemia."}, {"position": 4, "text": "Hipercalcemia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2025-v0-141', '2340c02874401ff94f5da9e925f4b0a669e17d33', 2025, 0, 141, false, false, 'Oncología', NULL, '¿A cuál de las siguientes proteínas presentes en la superficie celular se une el fármaco pembrolizumab?:', '[{"position": 1, "text": "PD-1."}, {"position": 2, "text": "PD-L1."}, {"position": 3, "text": "CTLA-4."}, {"position": 4, "text": "HER2."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-142', '1826ee2807e0153c036d7c5962989c2cd3983abc', 2025, 0, 142, false, false, 'Oncología', NULL, '¿Cuál de estos pacientes en tratamiento con quimioterapia cumple criterios de neutropenia febril?:', '[{"position": 1, "text": "Mujer de 38 años intervenida de cáncer de mama en curso de quimioterapia adyuvante que acude a urgencias por temperatura de 38,5ºC, odinofagia, rinorrea y buen estado general. Neutrófilos 400/mm3."}, {"position": 2, "text": "Mujer de 68 años intervenida de cáncer de colon estadio IV en curso de quimioterapia de primera línea que acude a urgencias por temperatura de 37,8ºC, diarrea y mucositis grado 2. Hemodinamicamente estable. Neutrófilos 300/mm3."}, {"position": 3, "text": "Hombre de 50 años intervenido de adenocarcinoma gástrico en curso de quimioterapia adyuvante que acude a urgencias por escalofríos y temperatura de 37,5ºC sin otra sintomatología acompañante. Neutrófilos 600/mm3."}, {"position": 4, "text": "Hombre de 65 años afecto de adenocarcinoma gástrico metastásico en curso de quimioterapia de segunda línea con ECOG 1 que acude a urgencias por temperatura de 38,6 ºC y diarrea grado 1. Neutrófilos 700/mm3."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-143', '0450c0fc7e0560825cd895fd7cdb544875099784', 2025, 0, 143, false, false, 'Oncología', NULL, 'En un paciente con cáncer colorrectal metastásico irresecable RAS nativo y con pérdida de expresión de proteínas reparadoras del ADN (MSI-H). ¿Cuál debe ser el tratamiento de elección de primera línea?:', '[{"position": 1, "text": "Quimioterapia + Anti-EGFR."}, {"position": 2, "text": "Inmunoterapia."}, {"position": 3, "text": "Quimioterapia."}, {"position": 4, "text": "Quimioterapia + Anti-VEGFR."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-144', '0d441db0fb3e7d7511e1587d6d0e7ebd09626ef7', 2025, 0, 144, false, false, 'Hematología', NULL, 'Hombre de 48 años, exfumador hasta el 2.020, con antecedente de nefrectomía parcial izquierda en el 2.020 por carcinoma de células renales, tipo célula clara, grado 2/4, pT1b, que acude por autopalparse una adenopatía laterocervical alta hace 4 meses. En la ecografía de cuello se identifican 2 lesiones nodulares submaxilares y en el TC de cuello se informa de una lesión nodular de partes blandas derecha que corresponde probablemente a una adenopatía sospechosa. Se indica biopsia de la lesión donde se observa una proliferación neoplásica constituida por células con marcada atipia citológica que se disponen con un patrón de crecimiento difuso. El estudio inmunohistoquímico es positivo para CD20, y negativo para CD3, CD30, CD15 y CKAE1-AE3. En estos casos se completa el estudio con CD10, Bcl6 y MUM1 para indicar el fenotipo de la neoplasia. ¿Cuál es el diagnóstico anatomopatológico?:', '[{"position": 1, "text": "Linfoma Hodgkin variante clásica."}, {"position": 2, "text": "Linfoma B difuso de célula grande."}, {"position": 3, "text": "Linfoma T periférico."}, {"position": 4, "text": "Metástasis de carcinoma."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-145', '91f3ab2013b949e837e5b6a7cce6f85fa9910f21', 2025, 0, 145, false, false, 'Hematología', NULL, 'Hombre de 17 años con hemofilia A grave e inhibidor de alto título frente al FVIII que presenta sangrado agudo a nivel articular. ¿Cuál de los siguientes tratamientos es el más indicado para controlar la hemorragia?', '[{"position": 1, "text": "Desmopresina."}, {"position": 2, "text": "Emicizumab."}, {"position": 3, "text": "Ácido tranexámico."}, {"position": 4, "text": "Factor VII activado recombinante."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-146', '355a8311fade32c92e6895dc18cf0bdc3cabf443', 2025, 0, 146, false, false, 'Hematología', NULL, 'Hombre de 76 años que es intervenido por recambio protésico de cadera derecha tras traumatismo. Entre los antecedentes personales destaca hipertensión arterial en tratamiento farmacológico y recambio protésico de rodilla izquierda hace 3 meses por artrosis evolucionada. Al cuarto día del postoperatorio se detecta trombopenia de 52.000/mm3 con cifras de hemoglobina y leucocitos normales. El estudio de coagulación y la bioquímica es normal. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Púrpura trombótica trombocitopénica."}, {"position": 2, "text": "Coagulación intravascular diseminada."}, {"position": 3, "text": "Trombopenia inducida por heparina."}, {"position": 4, "text": "Síndrome hemolítico urémico."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-147', '378e570aa69f9605f6b3a108ea566d56aae37c40', 2025, 0, 147, false, false, 'Hematología', NULL, '147. Los siguientes tipos de linfoma pueden ser originados por virus. ¿Cuál de ellos es producido por el virus herpes humano tipo 8 (KSHV/HHV8)?', '[{"position": 1, "text": "Leucemia-linfoma T del adulto."}, {"position": 2, "text": "Linfoma primario de cavidades."}, {"position": 3, "text": "Linfoma de Burkitt."}, {"position": 4, "text": "Granulomatosis linfomatoide."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-148', 'd403369e0fbbf9370076a27823dc5b8d5d760990', 2025, 0, 148, false, false, 'Hematología', NULL, 'Mujer de 50 años diagnosticada de síndrome mielodisplásico con monosomía del cromosoma 7 (45 XX -7 [20]) es sometida a un trasplante hematopoyético alogénico con sangre de cordón umbilical de un hombre compatible procedente de un banco de otro país. A los tres meses del trasplante con recuperación completa de las cifras hematológicas periféricas se realiza una punción de médula ósea, que no presenta alteraciones morfológicas y un estudio cromosómico con un cariotipo 47 XXY [20]. ¿Cuál es la explicación de estos hallazgos?:', '[{"position": 1, "text": "El donante tiene un síndrome de Klinefelter no diagnosticado."}, {"position": 2, "text": "En la médula ósea coexisten células del donante y del receptor (quimerismo mixto)."}, {"position": 3, "text": "Tras el trasplante ha existido un fenómeno de fusión celular entre las células del donante y receptor que ha originado el nuevo cariotipo."}, {"position": 4, "text": "En el cariotipo realizado precozmente tras un trasplante hematopoyético es habitual encontrar alteraciones cromosómicas transitorias de este tipo que carecen de significación clínica."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-149', 'e1f7e1987cebede7f7cfd43d93a99676f6ed8c7b', 2025, 0, 149, false, false, 'Geriatría', NULL, 'Mujer de 90 años sin alergias medicamentosas conocidas, con HTA y gonalgia nocturna por gonartrosis derecha de intensidad leve-moderada de tres meses de evolución. Refiere que no toma ninguna medicación y se confirma que realiza las medidas higiénicas del sueño correctamente. Consulta a su médico de atención primaria por insomnio de conciliación y mantenimiento que le interfiere con sus actividades diarias. ¿Qué fármaco es más adecuado iniciar en este caso?:', '[{"position": 1, "text": "Paracetamol."}, {"position": 2, "text": "Diazepam."}, {"position": 3, "text": "Mirtazapina."}, {"position": 4, "text": "Trazodona."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-150', '14b977e0d558c4f6cb59996fafc3bfc5403c34c7', 2025, 0, 150, false, false, 'Geriatría', NULL, '150. En los pacientes mayores con síndrome de inmovilidad una de las siguientes manifestaciones clínicas o consecuencias NO es atribuible al mismo:', '[{"position": 1, "text": "Déficit intelectual."}, {"position": 2, "text": "Aumento de la frecuencia cardíaca."}, {"position": 3, "text": "Reducción de la sensibilidad a la insulina."}, {"position": 4, "text": "Balance nitrogenado positivo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-151', '78368e2068b1318f38697f427e1bb52b36345703', 2025, 0, 151, false, false, 'Geriatría', NULL, '151. Hombre de 85 años diagnosticado de enfermedad de Alzheimer en tratamiento con donepezilo. Desde hace una semana y coincidiendo con una infección urinaria por germen sensible a amoxicilina/clavulánico, presenta un trastorno grave de conducta; por todo ello, recibe tratamiento con dicho antibiótico y con risperidona 1 mg cada 12 horas. Hoy la familia lo trae a su consulta porque a pesar de mejorar la infección de orina, está muy entumecido, necesitando ayuda para comer y vestirse, no es capaz de deambular sin ayuda, duerme de día y presenta insomnio de madrugada. Ante esta situación clínica señale la respuesta CORRECTA:', '[{"position": 1, "text": "Probablemente se trata de un efecto secundario de la risperidona, por lo que se debe retirar."}, {"position": 2, "text": "Se debe tratar el insomnio de madrugada añadiendo benzodiacepinas."}, {"position": 3, "text": "Hay que esperar a que se resuelva totalmente la infección urinaria para cambiar la medicación actual."}, {"position": 4, "text": "Ha empeorado la demencia y se debe añadir memantina al tratamiento de base con donepezilo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-152', '9b92c549777826e11febf5471eb9ee6363e7ba79', 2025, 0, 152, false, false, 'Geriatría', NULL, 'Los criterios STOPP/START tienen el objetivo de optimizar la medicación y minimizar las reacciones adversas a los medicamentos durante la revisión de la medicación en adultos mayores. En cuanto a los criterios START (versión 3, última versión), ¿cuál deberíamos valorar indicar?:', '[{"position": 1, "text": "Estrógenos tópicos vaginales en la vaginitis atrófica sintomática."}, {"position": 2, "text": "Vacuna antitetánica ante una herida abierta."}, {"position": 3, "text": "Parche de lidocaína tópica para el dolor articular generalizado."}, {"position": 4, "text": "Corticosteroides inhalados en el EPOC estadio GOLD 1-2."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-153', '9344949e7bc60876b5425e82bbbea64e9c2619c4', 2025, 0, 153, false, false, 'Endocrinología', NULL, 'En la actualidad se definen varios estadios o etapas de la diabetes tipo 1 autoinmune. Señale cuál es la definición CORRECTA:', '[{"position": 1, "text": "El estadio o etapa 3 se caracteriza por la autoinmunidad y tolerancia alterada de la glucosa (ya sea basal o tras test de sobrecarga con glucosa oral)."}, {"position": 2, "text": "El estadio o etapa 1 se caracteriza por presencia única de autoinmunidad contra las células de los islotes sin aparición de alteraciones de la glucosa."}, {"position": 3, "text": "El estadio o etapa 2 se caracteriza por hiperglucemia con cifras que definen diabetes."}, {"position": 4, "text": "La luna de miel aparece en el estadio 2, con la hiperglucemia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-154', '55ee72ae5ff16bb99f3db8ebb5b48e38dc28eb15', 2025, 0, 154, false, false, 'Endocrinología', NULL, '154. Mujer que acude a consulta de endocrino por secreción láctea por el pezón y una cifra de prolactina en sangre de 45 µg/L (normal <20 µg/L). ¿Cuál es la actitud diagnóstica más apropiada?:', '[{"position": 1, "text": "La primera medida a realizar es una resonancia cerebral porque lo más probable es que sea un macroadenoma secretor de prolactina."}, {"position": 2, "text": "Se debe interrogar sobre la toma de fármacos antagonistas del receptor de dopamina o un posible embarazo."}, {"position": 3, "text": "Las pruebas de laboratorio para su correcta caracterización consisten en la medición aislada de prolactina."}, {"position": 4, "text": "Se debe descartar un hipertiroidismo primario."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-155', 'b396ba258e6a5dd6973d34957b78edaeb5d58f3f', 2025, 0, 155, false, false, 'Ginecología y Obstetricia', NULL, '155. La estrategia de cribado de diabetes gestacional en un solo paso consiste en:', '[{"position": 1, "text": "Test de sobrecarga oral de glucosa con 50 gr de glucosa."}, {"position": 2, "text": "Test de sobrecarga oral de glucosa con 75 gr de glucosa."}, {"position": 3, "text": "Test de sobrecarga oral de glucosa con 90 gr de glucosa."}, {"position": 4, "text": "Test de sobrecarga oral de glucosa con 100 gr de glucosa."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-156', 'f43c66b36c1f525ed9e203771e20316fe600eb87', 2025, 0, 156, false, false, 'Endocrinología', NULL, '156. Está de guardia en urgencias y valora a un hombre de 45 años que consulta por vómitos de 2-3 días de evolución con disconfort abdominal y astenia intensa desde hace 1 mes. La presión arterial en triaje es 85/40 mmHg. Cuando lo explora objetiva hiperpigmentación parcheada en la cavidad oral y en la analítica destaca sodio de 134 mEq/L. ¿Cuál es su primera opción diagnóstica de las expuestas a continuación?:', '[{"position": 1, "text": "Hemocromatosis."}, {"position": 2, "text": "Síndrome de Peutz Jeghers."}, {"position": 3, "text": "Enfermedad de Addison."}, {"position": 4, "text": "Síndrome Stevens-Johnson."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-157', 'c0978b0dcedf413dc9d769cdfa19ff3f2365dc76', 2025, 0, 157, false, false, 'Endocrinología', NULL, '157. ¿Qué fármaco de los mencionados a continuación ha de tenerse en cuenta cuando se evalúa a un paciente con hiperparatiroidismo?:', '[{"position": 1, "text": "Hidroclorotiazida."}, {"position": 2, "text": "Losartán."}, {"position": 3, "text": "Amlodipino."}, {"position": 4, "text": "Doxazosina."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-158', '68e3f25d381985176c48adbfa6b0038c69c91be9', 2025, 0, 158, false, false, 'Endocrinología', NULL, '¿Cuál de las siguientes causas de hipertiroidismo puede cursar con TSH normal o elevada?:', '[{"position": 1, "text": "Tirotoxicosis facticia."}, {"position": 2, "text": "Struma ovarii."}, {"position": 3, "text": "Adenoma hipofisario productor de TSH."}, {"position": 4, "text": "Hipertiroidismo por beta-HCG durante la gestación."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-159', 'e3834be2b8f78309324128ce5a107dfa23f29db9', 2025, 0, 159, false, false, 'Endocrinología', NULL, 'Hombre de 58 años, fumador de 30 cigarrillos diarios desde los 19 años, con antecedentes de hipertensión arterial mal controlada, diabetes mellitus tipo 2 y obesidad grado I. En estudio por disnea de 5 meses de evolución, asociando pérdida de peso, astenia e hiporexia. Como parte del estudio se realiza TC toracoabdominal describiéndose la presencia de un nódulo pulmonar inespecífico de 1,1 cm en lóbulo superior derecho sin datos de malignidad y un nódulo en la glándula suprarrenal derecha de 1,9 cm. ¿Qué pruebas complementarias habría que solicitar para el estudio del incidentaloma suprarrenal?:', '[{"position": 1, "text": "Test de supresión con 8 mg de dexametasona (DXM) nocturno, metanefrinas libres plasmáticas y resonancia magnética centrada en suprarrenales."}, {"position": 2, "text": "Metanefrinas fraccionadas en orina de 24 horas, test de supresión con 1 mg DXM nocturno, ratio renina/aldosterona y PET-TC con 18FDG."}, {"position": 3, "text": "Metanefrinas fraccionadas en orina de 24 horas, test de supresión con 1 mg DXM nocturno, ratio aldosterona/renina y TC centrada en adrenales."}, {"position": 4, "text": "Cortisol libre urinario, metanefrinas fraccionadas en muestra aislada de orina, ratio aldosterona/renina y resonancia magnética centrada en suprarrenales."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-160', '64b53293848d6c01fbb5c7b1c713da21c62fd97e', 2025, 0, 160, false, false, 'Dermatología', NULL, 'Mujer de 25 años, sin enfermedades previas conocidas, que consulta por lesión en labio inferior. No es la primera vez que le sucede desde la adolescencia, siempre en la misma zona, inicia dolor y aparece una lesión vesiculosa que se autolimita en una semana aproximadamente. Respecto al abordaje de la enfermedad de esta paciente, es INCORRECTO que:', '[{"position": 1, "text": "Si presenta más de tres episodios anuales está indicado realizar profilaxis con un antiviral como valaciclovir 500 mg cada 12 horas o 1 g al día, durante seis meses."}, {"position": 2, "text": "Si es una única lesión y es un cuadro leve puede no realizarse ningún tratamiento o bien realizar tratamiento tópico con fomentos de sulfato de zinc o de cobre."}, {"position": 3, "text": "Si existe riesgo de afectación oftálmica estaría indicado tratar con un antivírico como valaciclovir a razón de 1 g cada 8 horas durante 7 días vía oral."}, {"position": 4, "text": "Es necesario recomendarle una adecuada protección solar pues la exposición solar puede motivar recurrencias."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-161', 'd2bcb4d426422fe6df519c9cf1b4c69138486a11', 2025, 0, 161, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 50 años que presenta una erupción generalizada especialmente en el tronco. Refiere malestar general desde hace pocos días. Hoy acude porque ha tenido fiebre la noche anterior y se ha visto una mancha negra en la zona abdominal. A la exploración física, la mancha negra corresponde a una pequeña escara. El paciente es cazador y acudió recientemente a una batida. Sobre el abordaje del caso es cierto que:', '[{"position": 1, "text": "Es una enfermedad de declaración obligatoria."}, {"position": 2, "text": "El tratamiento de elección es la amoxicilina, un gramo cada 8 horas durante 7 días."}, {"position": 3, "text": "Debe derivarse a un centro hospitalario."}, {"position": 4, "text": "En la mayoría de los casos, la fiebre precede al exantema y la escara."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-162', 'dd42385031e348b11a8446e682145381a1202390', 2025, 0, 162, false, false, 'Enfermedades Infecciosas', NULL, 'Respecto al tratamiento de la foliculitis, es correcto que:', '[{"position": 1, "text": "El tratamiento de elección incluso en formas localizadas es la cloxacilina vía oral."}, {"position": 2, "text": "En caso de alergia a la penicilina, la opción más adecuada sería el ciprofloxacino oral."}, {"position": 3, "text": "Debe realizarse tratamiento oral en pacientes con valvulopatía reumática por el riesgo de endocarditis."}, {"position": 4, "text": "Es una infección fundamentalmente estreptocócica por Streptococcus pyogenes."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-163', '467b87ac7494229a7351e2c2d141dcd2aaabf85b', 2025, 0, 163, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 62 años con antecedentes de hipertensión arterial, diabetes mellitus tipo 2 y en tratamiento con infliximab por artritis reumatoide, se presenta en urgencias con fiebre, tos seca, mialgias y disnea leve de 5 días de evolución. A la exploración física, la saturación de oxígeno es del 90% con aire ambiente. Se realiza una radiografía de tórax que muestra opacidades en vidrio deslustrado bilaterales. La PCR en frotis nasofaríngeo para SARS-CoV-2 resulta positiva. ¿Cuál de las siguientes opciones es la conducta más apropiada?:', '[{"position": 1, "text": "Administrar plasma de convaleciente y anticoagulación profiláctica."}, {"position": 2, "text": "Iniciar tratamiento con antibióticos de amplio espectro y corticoides a dosis altas."}, {"position": 3, "text": "Monitorización ambulatoria con seguimiento telefónico y tratamiento sintomático."}, {"position": 4, "text": "Ingreso hospitalario para tratamiento con remdesivir y dexametasona."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-164', '257a9763d91f008df3b61689927b673f9d9fd0d6', 2025, 0, 164, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 56 años, nacido en Paraguay, acude a consulta, remitido por su médico de familia, por disnea progresiva y palpitaciones. Tiene un ECG en el que se observa extrasístoles ventriculares y bloqueo completo de rama derecha. Aporta una serología por ELISA IgG positiva frente a Trypanosoma cruzi. ¿Cuál de las siguientes respuestas es INCORRECTA?:', '[{"position": 1, "text": "Se debe realizar una prueba serológica con inmunofluorescencia para detectar IgG frente a T. cruzi."}, {"position": 2, "text": "La prueba de reacción en cadena de la polimerasa (PCR) tiene un valor diagnóstico limitado en esta fase de la enfermedad."}, {"position": 3, "text": "Debe iniciar tratamiento con benznidazol para modificar la evolución de la enfermedad."}, {"position": 4, "text": "Si se confirma el diagnóstico, debe estudiar a los familiares cercanos para identificar otros casos."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-165', '651fc70bb05579a22828e1221f5385d49c28ea73', 2025, 0, 165, false, false, 'Reumatología', NULL, 'Una mujer de 45 años con antecedentes de pleuritis hace 3 años y episodios ocasionales de poliartritis en los últimos 8 meses, fue diagnosticada de LES hace un mes tras un ingreso por fatiga y dolor torácico opresivo de esfuerzo, donde se objetivó una Hb de 5,8 g/dL y VCM de 109 fL por una anemia hemolítica autoinmune. El resto de la analítica mostró una linfopenia de 900/mm3, plaquetas en rango de normalidad, función hepática, creatinina y ionograma normales, tiempo de protrombina 85%, TTPA se muestra prolongado (ratio de 1,8). Existe hipocomplementemia C3 y C4, ANA 1/640, con Anti-DNA +. Fue dada de alta con corticoides, hidroxicloroquina y belimumab semanal subcutáneo. A las tres semanas del alta refiere sensación disneica de 48 horas de evolución sin otros síntomas acompañantes, la Hb de urgencias es de 10,2 gr/dL. ¿Cuál de las siguientes determinaciones de laboratorio deberíamos realizar en primer lugar?:', '[{"position": 1, "text": "Dímero D."}, {"position": 2, "text": "Proteínas en orina."}, {"position": 3, "text": "NT-proBNP."}, {"position": 4, "text": "Test de Coombs."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-166', 'c733d1fb82dfe973632ced2a397f2fefb1f7115a', 2025, 0, 166, false, false, 'Enfermedades Infecciosas', NULL, 'Mujer de 72 años, procedente del medio rural que acude al servicio de urgencias por un cuadro de dolor abdominal, vómitos y diarrea líquida, que posteriormente se hace sanguinolenta, de 6 días de duración. No refiere fiebre ni tratamiento antibiótico previo. Se toman muestras para hemocultivo y estudio microbiológico de las heces y se inicia tratamiento con fluidoterapia intensiva. 48 horas después se observa disminución del nivel de conciencia y la presencia de anemia (hematocrito de 25%, hemoglobina de 7,9 g/dL), trombopenia (plaquetas de 60.000/mL), creatinina de 3,2 mg/dL, hematuria y hemoglobinuria. En el estudio de sangre periférica se aprecian abundantes esquisicotios circulantes (más del 10%). Señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Debe tratar de identificar infección por E. coli, serotipo 0157:H7 y detección por PCR de toxina Shiga (Stx1 y/o Stx2) y genes relacionados."}, {"position": 2, "text": "Debe iniciar tratamiento antibiótico."}, {"position": 3, "text": "El cuadro clínico y analítico descarta la posibilidad de infección por Clostridium difficile."}, {"position": 4, "text": "La plasmaféresis no es útil en esta paciente."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-167', 'c07a2d6745191ff0441b3bc4eb7a1560f32853d9', 2025, 0, 167, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Mujer de 54 años de edad que acude a su consulta para estudio y evaluación del riesgo vascular. Entre sus antecedentes más relevantes, destacan un infarto agudo de miocardio a los 51 y a los 53 años de edad, hipertensión arterial controlada y un perfil lipídico con tratamiento hipolipemiante de alta intensidad de: colesterol total 120 mg/dL, cHDL 60 mg/dL cLDL 50 mg/dL, TG 128 mg/dL. HB1AC de 5.2% y glucemia plasmática en ayunas normal. Nunca ha fumado. Índice de masa corporal de 23 Kg/m2. De las siguientes pruebas o determinaciones que se exponen a continuación, ¿qué es más útil para determinar el riesgo y la etiología de eventos recurrentes en esta paciente?:', '[{"position": 1, "text": "Determinación de ApoB."}, {"position": 2, "text": "Determinación de ApoA."}, {"position": 3, "text": "Determinación de Lp(a) o lipoproteína a."}, {"position": 4, "text": "Determinación de proteína C reactiva."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-168', '6eb1fcbbd4778039e3866499cc9b57b4636ed182', 2025, 0, 168, false, false, 'Enfermedades Infecciosas', NULL, 'Mujer de 28 años sin enfermedades previas, recién llegada de los Estados Unidos de América, donde ha estado practicando espeleología en el valle del Ohio durante un par de semanas, presenta clínica de infección respiratoria consistente en tos, fiebre, sensación disneica y artralgias, lesiones cutáneas nodulares y dolorosas, eritematosas y calientes en la zona pretibial. ¿En qué enfermedad hay que pensar?', '[{"position": 1, "text": "Aspergilosis pulmonar."}, {"position": 2, "text": "Esporotricosis."}, {"position": 3, "text": "Criptococosis pulmonar."}, {"position": 4, "text": "Histoplasmosis."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-169', '2d9e4aa0448fe65470e25958477b6ff1f7920faf', 2025, 0, 169, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 53 años, sin antecedentes patológicos, acude al hospital por fiebre de 10 días de evolución, con intensa cefalea retroorbitaria y una importante sensación de fatiga. No refiere dolor musculoesquelético, lesiones cutáneas ni ningún otro síntoma acompañante. A lo largo de 15 días de ingreso se objetiva fiebre persistente y la aparición de discreta ictericia conjuntival. La exploración respiratoria, cardíaca, abdominal y neurológica es normal. La analítica muestra VSG 97 mm/h, PCR 24,5 mg/dL, GOT 156 U/L, GPT 148 U/L, FA 410 U/L, GGT 794 U/L, bilirrubina total 5,5 mg/dL a expensas de la bilirrubina directa, hemoglobina 11,5 g/dL, recuento leucocitario normal, plaquetas 648.000/mm3, función renal e ionograma normales, tiempo de protrombina normal pero TTPA ratio 1,8. Los anticuerpos antinucleares (ANA) son positivos a títulos 1/160. Una ecografía abdominal no muestra ninguna alteración destacable. Desde el punto de vista clínico y a la vista de los datos analíticos, ¿cuál de las siguientes enfermedades es la que se ajusta mejor con nuestro paciente?:', '[{"position": 1, "text": "COVID-19."}, {"position": 2, "text": "Fiebre Q aguda."}, {"position": 3, "text": "Leptospirosis grave (enfermedad de Weil)."}, {"position": 4, "text": "Colangitis esclerosante primaria."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-170', 'ae6a446f290f2b48488238855800e99c161aca4f', 2025, 0, 170, false, false, 'Aparato Digestivo', NULL, 'Hombre de 38 años con dependencia alcohólica grave. Ha tenido varios ingresos por pancreatitis aguda en el contexto de ingesta de alcohol e hipertrigliceridemia grave. Acude a consulta 12 meses después del último episodio de pancreatitis. No presenta clínica que sugiera insuficiencia pancreática exocrina. Niega reiteradamente ingesta de alcohol. Sigue tratamiento con estatinas y fibratos que asegura tomárselos. Aporta un análisis básico reciente de su empresa con los siguientes datos: colesterol 300 mg/dL, cHDL 42 mg/dL, TG 1102 mg/dL, cLDL no calculable por Friedewald. Colesterol no-HDL 258 mg/dL, ApoB 90 mg/dL, Lp(a) 38 nmol/L (normal <125 nmol/L). En dicho análisis hay un dato, además de la hipertrigliceridemia, que sugiere que el paciente continúa ingiriendo alcohol. Señálelo.', '[{"position": 1, "text": "ApoB."}, {"position": 2, "text": "cHDL."}, {"position": 3, "text": "Lp(a)."}, {"position": 4, "text": "Colesterol total."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-171', '1a8f04ec519eade87ab31c3f7fed39eeaefb3f91', 2025, 0, 171, false, false, 'Cirugía General', NULL, 'Respecto a las infecciones de las heridas quirúrgicas, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Diabetes mellitus, malnutrición, obesidad e inmunosupresión son factores de riesgo del paciente para desarrollar infecciones de las heridas quirúrgicas."}, {"position": 2, "text": "El control intensivo perioperatorio de la glucemia es una buena práctica de prevención de las infecciones de herida quirúrgica."}, {"position": 3, "text": "La mayoría de las recomendaciones sobre profilaxis antibiótica en cirugía cardíaca aconsejan mantener los antibióticos al menos 48 horas tras el procedimiento quirúrgico."}, {"position": 4, "text": "La antibioterapia local se emplea como método de profilaxis antimicrobiana y tratamiento antibiótico, sobre todo en la sustitución de prótesis articulares infectadas."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-172', 'a1095b43840f7487083b6c64a0cfd16ff6839882', 2025, 0, 172, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 37 años con infección VIH ha dejado de tomar el tratamiento por razones personales hace 3 meses; estaba tomando una combinación de dos inhibidores de transcriptasa inversa y un inhibidor de la integrasa. En la evaluación llevada a cabo en este momento tiene 120 linfocitos CD4/mm3 y una carga viral de VIH-1 de 80.000 copias/mL. Estamos pendientes del estudio de resistencias. ¿Qué debemos recomendarle en este momento?:', '[{"position": 1, "text": "Reiniciar el tratamiento con lo mismo con lo que estaba previamente."}, {"position": 2, "text": "Esperar a tener el resultado del estudio de resistencias para orientar el tipo de tratamiento en función de las mutaciones identificadas."}, {"position": 3, "text": "Prescribir a partir de ahora un régimen basado en inhibidores de proteasa por su mayor barrera genética a las resistencias."}, {"position": 4, "text": "Iniciar doble terapia con inhibidores de integrasa."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-173', 'ed67b473e9b7f611fe573039ed83b8878023cbed', 2025, 0, 173, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 55 años con antecedentes de cáncer de pulmón (estadio IV). Su madre murió a los 65 años por un episodio de broncoaspiración. Consulta por debilidad muscular en los muslos y disfagia. Exploración física: fuerza en posas 4+/5, cuádriceps 3/5, deltoides 5/5. Presenta ptosis palpebral bilateral y no tiene diplopía. Los valores de CPK eran 900 U/L (normal <150 U/L) y los de aldolasa, 7 U/L (normal <6 U/L). Se practicó una biopsia en el músculo vasto lateral externo del muslo derecho, en la cual se objetivó variabilidad en el tamaño de fibras, aumento del tejido conectivo, imágenes de pseudodivisión celular y vacuolas ribeteadas; no se observó infiltrado inflamatorio. ¿Qué es lo más probable que le suceda al paciente?:', '[{"position": 1, "text": "Distrofia oculofaríngea."}, {"position": 2, "text": "Miopatía mitocondrial."}, {"position": 3, "text": "Miastenia gravis."}, {"position": 4, "text": "Miositis con cuerpos de inclusión."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-174', 'd62f1c71e97297f45d31b5bc98e9046da377b4ff', 2025, 0, 174, false, false, 'Reumatología', NULL, 'Mujer de 81 años consulta por cuadro de 1 mes de duración de astenia, febrícula, pérdida de unos 4 kg de peso, cefalea hemicraneal izquierda y dolor en la zona de los hombros y de las caderas, que le dificulta los movimientos después de estar en reposo. Se palpa una zona engrosada y dolorosa en el territorio de la arteria temporal izquierda. Respecto al proceso diagnóstico de esta paciente, señale la opción INCORRECTA:', '[{"position": 1, "text": "La vasculitis sistémica que se sospecha con mayor probabilidad es una vasculitis de gran vaso."}, {"position": 2, "text": "En el análisis, la normalidad de la velocidad de sedimentación globular apoya el diagnóstico de esta vasculitis."}, {"position": 3, "text": "Es frecuente observar afectación de la pared arterial de la aorta y sus ramas principales mediante pruebas de imagen."}, {"position": 4, "text": "Una biopsia de la arteria temporal que muestre un infiltrado inflamatorio en la pared arterial confirmaría el diagnóstico de arteritis de células gigantes."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-175', '6c9d3cb4152427a3bf76564c24c72306db68bde0', 2025, 0, 175, false, false, 'Reumatología', NULL, '¿Cuál de las siguientes manifestaciones clínicas es la más característica de la miopatía de la dermatomiositis?:', '[{"position": 1, "text": "Dificultad para andar."}, {"position": 2, "text": "Dificultad para subir escaleras."}, {"position": 3, "text": "Dificultad para abrocharse los botones."}, {"position": 4, "text": "Dolor muscular."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-176', '23e6c97c529ed34561e855df737ad5c44c337767', 2025, 0, 176, false, false, 'Reumatología', NULL, 'Mujer de 38 años que consulta por la presencia de dolor ocular, ojo rojo bilateral, hipersensibilidad a la luz y disminución de la agudeza visual. La historia clínica se completa con antecedentes de aftas bucales dolorosas y recidivantes y un diagnóstico previo de eritema nodoso hace 2 años. En la exploración oftalmológica se observa panuveitis bilateral con signos de vasculitis retiniana bilateral. Señale la respuesta correcta sobre el diagnóstico y tratamiento de la enfermedad que sospecha en esta paciente:', '[{"position": 1, "text": "El hallazgo de HLA B*51 confirma el diagnóstico de sospecha."}, {"position": 2, "text": "Las úlceras bucales dejan cicatriz en la mayoría de los casos."}, {"position": 3, "text": "Debe instaurar tratamiento precoz e intensivo con glucocorticoides sistémicos e inmunosupresión con azatioprina."}, {"position": 4, "text": "La adición al tratamiento de anticuerpos monoclonales anti TNF alfa o ciclosporina no mejora el control de la uveitis."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-177', '5124599e9f06395fd8093483725795b1a808c2b5', 2025, 0, 177, false, false, 'Bioética y Medicina Legal', NULL, 'Mujer de 80 años que ingresa en el hospital para estudio de anemia tras ser llevada por sus hijos a urgencias por rectorragia y decaimiento físico. Clínicamente se encuentra estable. Está diagnosticada de un deterioro cognitivo, con ideación y juicio frecuentemente incoherentes y alteraciones conductuales para lo que toma risperidona. Se sospecha neoplasia maligna de colon y se plantea realizar una colonoscopia. Usted verifica que la paciente es incapaz de entender adecuadamente lo que se le explica sobre tal prueba, su naturaleza, objetivos, posibles complicaciones, o sus consecuencias diagnósticas y eventualmente terapéuticas. En tal caso, ¿cuál de las siguientes respuestas es correcta?:', '[{"position": 1, "text": "El médico queda eximido de plantear un proceso de consentimiento informado a la paciente, y se considera suficiente su criterio como médico para que se realice la colonoscopia."}, {"position": 2, "text": "El médico deberá solicitar la comparecencia del Juez, para que autorice la prueba, ante la incapacidad intelectual de la enferma para decidir convenientemente por sí misma."}, {"position": 3, "text": "Por no tener la paciente capacidad para decidir, deben hacerlo por ella sus familiares, debiendo quedar constancia escrita en el impreso de consentimiento informado."}, {"position": 4, "text": "Es jurídicamente aceptable un acuerdo entre el médico y los familiares de la enferma basado en un consentimiento informado verbal para que se practique la colonoscopia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-178', '3322efd9ae93b5de6d6522ea4cc11828d3055206', 2025, 0, 178, false, false, 'Bioética y Medicina Legal', NULL, 'Atiende a una paciente ingresada desde hace tres semanas en la unidad de cuidados intensivos por un cuadro de shock séptico respiratorio. Su evolución durante el ingreso no ha sido favorable y todavía continúa dependiente de ventilación mecánica invasiva. En los últimos días, tras recibir la información de que probablemente precise ventilación mecánica a medio-largo plazo, durante los periodos en que la paciente ha estado despierta, ha manifestado de forma clara su deseo de no continuar utilizando el ventilador. La paciente afirma comprender las consecuencias de esta decisión. Este caso habla de:', '[{"position": 1, "text": "Rechazo al tratamiento."}, {"position": 2, "text": "Limitación del esfuerzo terapéutico o adecuación de medidas de tratamiento."}, {"position": 3, "text": "Suicidio asistido."}, {"position": 4, "text": "Eutanasia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-179', 'dd45b21dd37fb145079056de5e8cd9772bab1768', 2025, 0, 179, false, false, 'Cuidados Paliativos', NULL, 'En relación con el uso de opioides en pacientes que reciben cuidados paliativos, indique, de las siguientes afirmaciones, cuál es correcta:', '[{"position": 1, "text": "En la actualidad existen comercializados diferentes fármacos opioides para el tratamiento del dolor moderado o grave en personas que reciben cuidados paliativos, superando en perfil de efectos adversos y en efectividad a la morfina y relegándola a un papel testimonial."}, {"position": 2, "text": "La adicción es un problema creciente en pacientes que precisan morfina en su fase final de vida y es más frecuente cuando se emplean fármacos con efecto de larga duración (metadona o morfina de liberación prolongada)."}, {"position": 4, "text": "El fentanilo oral transmucoso tiene un perfil de acción que lo hace útil en el dolor crónico no irruptivo y de carácter crónico."}, {"position": 5, "text": "La metadona es un fármaco analgésico con escasa excreción renal por lo que es útil en personas con aclaramiento renal disminuido."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-180', '3aca4fdd888d9320482f2d64ac67f32526e0c874', 2025, 0, 180, false, false, 'Bioética y Medicina Legal', NULL, 'En relación con la atención en urgencias al paciente menor de edad y de acuerdo con la Ley de protección integral a la infancia y la adolescencia frente a la violencia, cuando el profesional sanitario advierta indicios de una situación de violencia ejercida sobre un menor, en un contexto en el que no exista una amenaza evidente sobre su salud o seguridad, tendrá obligación de comunicarlo de forma inmediata:', '[{"position": 1, "text": "A los servicios sociales competentes."}, {"position": 2, "text": "Al juzgado de guardia mediante parte de lesiones."}, {"position": 3, "text": "A las Fuerzas y Cuerpos de Seguridad."}, {"position": 4, "text": "Al Instituto de Medicina Legal y Ciencias Forenses de su demarcación."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-181', '27760124f9b1ffb1737da809e16cdd935db037f8', 2025, 0, 181, false, false, 'Bioética y Medicina Legal', NULL, 'En relación con la marca producida por el paso de la corriente eléctrica a través de la piel (también conocida como lesión electroespecífica o “marca de Jellinek”), ¿cuál de las siguientes afirmaciones es cierta?:', '[{"position": 1, "text": "La mayor parte de las lesiones producidas por la corriente eléctrica en medio doméstico y laboral proceden de fuentes de alto voltaje."}, {"position": 2, "text": "Las lesiones dérmicas dependen del efecto de un aumento de la temperatura generado sobre la dermis."}, {"position": 3, "text": "La corriente de bajo voltaje produce lesiones profundas, mientras que la de alto voltaje da lugar a lesiones superficiales adyacentes al punto de contacto con la corriente eléctrica."}, {"position": 4, "text": "La marca eléctrica es diagnóstica del lugar en el que se ha producido el contacto y, por tanto, el punto de entrada de la corriente en el cuerpo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-182', 'adfac100835822d0a6094d40a616c0656693db1e', 2025, 0, 182, false, false, 'Cuidados Paliativos', NULL, 'Hombre de 75 años con enfermedad de Alzheimer de 6 años de evolución, actualmente en estadio GDS-FAST 7c. Está institucionalizado en centro sociosanitario desde hace 1 año. En los últimos 6 meses tiene frecuentes episodios de broncoaspiración por los que ha acudido a Urgencias y han sido tratados con antibioterapia de amplio espectro con mejoría clínica. Acude nuevamente a urgencias por disnea en relación con nuevo episodio de broncoaspiración y negativa a la ingesta. ¿Cuál debe ser la actitud a seguir?:', '[{"position": 1, "text": "Evitar ingreso. Indicar sonda nasogástrica (SNG) con el fin de prevenir nuevas broncoaspiraciones y facilitar ingesta. Antibioterapia empírica con amoxicilina-clavulánico por SNG."}, {"position": 2, "text": "Ingresar para colocación de gastrostomía (PEG) con el fin de evitar nuevas broncoaspiraciones y facilitar ingesta. Antibioterapia empírica con piperacilina-tazobactam iv."}, {"position": 3, "text": "Evitar ingreso. No está indicada la colocación de sonda para nutrición enteral. Considerar adecuación del esfuerzo terapéutico evitando antibioterapia y dando cuidados de confort."}, {"position": 4, "text": "Ingresar para antibioterapia empírica con piperacilina-tazobactam, pero evitar la colocación de sonda para nutrición enteral. La curación del proceso infeccioso mejorará casi siempre la ingesta."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-183', '1372ef8bb76f61d763655d5120acbc470996460a', 2025, 0, 183, false, false, 'Atención Primaria', NULL, 'La telemonitorización domiciliaria ha demostrado beneficios en pacientes con insuficiencia cardíaca. Una mujer de 82 años con insuficiencia cardíaca y diabetes tratada con insulina está en programa de telemonitorización y remite cada semana una serie de parámetros a su médico de familia. La semana pasada presentaba presión arterial 140/85 mmHg. Glucemia capilar basal 120 mg/dL. Glucemia postprandial 2 h tras la comida 160 mg/dL. Peso 83 kg. Frecuencia cardíaca 72 lpm. Al recibir los parámetros de esta semana que se exponan a continuación, su médico decide citar a la paciente en consulta. ¿Cuál de los siguientes parámetros ha motivado dicha decisión?:', '[{"position": 1, "text": "Presión arterial 135/82 mmHg."}, {"position": 2, "text": "Peso 85 Kg."}, {"position": 3, "text": "Glucemia capilar basal 130 mg/dL."}, {"position": 4, "text": "Glucemia capilar postprandial 190 mg/dL."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-184', '8f996dc412c164b370b0fd2e0c6cbdb19f36c05d', 2025, 0, 184, false, false, 'Endocrinología', NULL, 'En un paciente con diabetes y obesidad en prevención secundaria cardiovascular, tratado con metformina y ISGLT2, que presenta mal control glucémico, ¿cuál es el fármaco de elección para mejorar dicho control?:', '[{"position": 1, "text": "Insulina."}, {"position": 2, "text": "Análogos del receptor del péptido similar al glucagón tipo 1 (arGLP-1)."}, {"position": 3, "text": "Sulfonilurea."}, {"position": 4, "text": "Repaglinida."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-185', 'b6b525a23db60816972cc73e010e4de896042c9f', 2025, 0, 185, false, false, 'Cuidados Paliativos', NULL, 'Mujer de 61 años con adenocarcinoma rectal avanzado. Presenta dolor neuropático con irradiación perineal y molestias urinarias en relación con masa presacra. Mejoró con tratamiento con opioides (morfina 60 mg cada 12h) pero no tolera más aumento de dosis ni fármacos adyuvantes. ¿Cuál es el tratamiento de elección?:', '[{"position": 1, "text": "Bloqueo del plexo celiaco."}, {"position": 2, "text": "Bloqueo del ganglio impar."}, {"position": 3, "text": "Bloqueo de nervios esplácnicos."}, {"position": 4, "text": "Bloqueo del nervio pudendo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-186', 'b331a8f587f019b0fe7f90537e515a198b959b9c', 2025, 0, 186, false, false, 'Medicina Intensiva y Urgencias', NULL, 'En una guardia de centro de salud avisan para atender a un hombre de 63 años, que ha sido sometido a bajas temperaturas, sin precisar cuánto tiempo ha estado en exposición. A su llegada, tiene una temperatura corporal de 28ºC. ¿Cuál de los siguientes hallazgos NO cabría esperar en este cuadro?:', '[{"position": 1, "text": "Taquipnea."}, {"position": 2, "text": "Fibrilación ventricular."}, {"position": 3, "text": "Alucinaciones."}, {"position": 4, "text": "Pupilas mióticas."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-187', '3d500ae1465e926d41903b39720a7f4d4c18891d', 2025, 0, 187, false, false, 'Atención Primaria', NULL, 'En cuanto al uso de anticonceptivos en mujeres jóvenes en las consultas de Atención Primaria, es importante tener en cuenta diversos aspectos para la prescripción. ¿Cuál de las siguientes es INCORRECTA?:', '[{"position": 1, "text": "Se ha de ofrecer consejo contraceptivo estructurado según los criterios de elegibilidad de la Organización Mundial de la Salud (OMS), e información tanto para la prevención de embarazos no planificados, como de enfermedades de transmisión sexual (ETS)."}, {"position": 2, "text": "Como método anticonceptivo de urgencias, las opciones recomendadas son la toma de levonorgestrel, de acetato de ulipristal o la inserción de un DIU de cobre."}, {"position": 3, "text": "Ante la indicación de anticonceptivos orales se recomienda el cribado rutinario de trombofilia y dislipemia y citologías de control anuales."}, {"position": 4, "text": "El riesgo de tromboembolia venosa con el consumo de anticonceptivos orales es bajo, siendo el riesgo menor en los de segunda generación, frente al mayor riesgo en los de tercera y cuarta generación."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-188', 'fd6e22e5addb5586f76145d4ab63d82251c111ed', 2025, 0, 188, false, false, 'Endocrinología', NULL, '¿Cuál de los siguientes fármacos debería evitarse en un paciente que presenta diabetes y obesidad por ser un fármaco que puede inducir aumento de peso?', '[{"position": 1, "text": "Metformina."}, {"position": 2, "text": "Sitagliptina."}, {"position": 3, "text": "Semaglutida."}, {"position": 4, "text": "Pioglitazona."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-189', '9298782a3fbf002c5d411c50fcdc63ddb7acc330', 2025, 0, 189, false, false, 'Cuidados Paliativos', NULL, 'Hombre de 69 años con adenocarcinoma de páncreas avanzado que presenta como principal sintomatología dolor de características mixtas tratado desde hace 3 meses con opioides con buen control (morfina 60 mg cada 12 horas) + adyuvantes (duloxetina 60 mg/día). Asocia astenia e hiporexia graves tratadas con corticoides desde hace 2 semanas (dexametasona 8 mg/día). Acude a consulta refiriendo somnolencia intensa y alucinaciones táctiles. En la analítica presenta como datos más destacables anemia de trastornos crónicos (Hb 10,6 g/dL) y empeoramiento de la función renal (CKD-EPI 26 mL/min). ¿Cuál es el diagnóstico más probable y la actitud a seguir?:', '[{"position": 1, "text": "Clínica neurológica por metástasis cerebrales. Realizar TC cerebral y aumentar dosis de corticoides."}, {"position": 2, "text": "Psicosis inducida por corticoides. Retirar corticoides."}, {"position": 3, "text": "Síndrome confusional agudo hipoactivo. Iniciar tratamiento con neurolépticos."}, {"position": 4, "text": "Neurotoxicidad por opioides. Reducir la dosis de morfina a la mitad."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-190', 'a1174f143e5ce3a696ac643a4d3fc62278987a70', 2025, 0, 190, false, false, 'Medicina Intensiva y Urgencias', NULL, 'Hombre de 36 años sin antecedentes de interés que ingresa en observación de urgencias en espera de intervención quirúrgica por fractura de fémur a nivel diafisario por accidente de tráfico. El paciente llega algo taquicárdico 102 lpm, con gafas nasales para mantener saturación de oxígeno en torno al 96%, 20 respiraciones por minuto y presión arterial 100/60 mmHg. Se procede a ajuste de analgesia y a las 20 horas de estancia en observación indican que el paciente puede ir a quirófano pero presenta un aumento de disnea con saturación del 89% con mascarilla tipo Venturi, 28 respiraciones por minuto, taquicardia a 110 lpm, fiebre de 38°C y se encuentra algo obnubilado. En la analítica destaca anemia y trombocitopenia. No presenta aumento de volumen en ninguna de las 2 piernas. ¿Qué prueba complementaria tiene mayor sensibilidad y especificidad para la sospecha diagnóstica de este paciente?', '[{"position": 1, "text": "AngioTC helicoidal con contraste."}, {"position": 2, "text": "Gammagrafía pulmonar de perfusión."}, {"position": 3, "text": "Radiografía de tórax."}, {"position": 4, "text": "Ecocardiografía."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2025-v0-191', '7808896aacf55513596b6c467711e546c5d1b014', 2025, 0, 191, false, false, 'Medicina Intensiva y Urgencias', NULL, 'Hombre de 72 años sin alergias medicamentosas, no fumador y con antecedentes de hipertensión, dislipemia y diabetes. En tratamiento con ácido acetilsalicílico, atorvastatina, enalapril y metformina. Acude a urgencias por agudización de lumbalgia crónica de meses de evolución. Refiere que el dolor no es irradiado, y no mejora mucho en reposo. Ha tomado varios analgésicos sin ninguna mejoría. A la exploración no presenta dolor en espinosas dorsolumbares, el signo de Lasegue es negativo, no presenta limitación a la movilidad, reflejos normales y no hay alteración de sensibilidad o fuerza. Pulsos pedios ausentes y tibiales débiles. No edemas de miembros inferiores. Ante la sospecha diagnóstica, ¿qué prueba nos daría el diagnóstico más rápidamente con mayor sensibilidad y especificidad?:', '[{"position": 1, "text": "Ecografía abdominal."}, {"position": 2, "text": "TC toraco-abdominal."}, {"position": 3, "text": "Resonancia magnética."}, {"position": 4, "text": "Radiografía de columna lumbosacra."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-192', 'f9a24d1666d14835a76169b96dcfb085b4dc4fc1', 2025, 0, 192, false, false, 'Enfermedades Infecciosas', NULL, 'Acude a urgencias un hombre de 34 años, sin diagnósticos previos, con antecedente de consumo de drogas por vía parenteral, con fiebre, tos no productiva y disnea progresiva de varias semanas de evolución. Se realiza radiografía de tórax que muestra infiltrado intersticial bilateral. En analítica sanguínea destaca linfopenia y lactato deshidrogenasa elevada. La saturación de oxígeno es del 88% respirando aire ambiente en reposo. ¿Cuál de las siguientes aseveraciones le parece INCORRECTA?:', '[{"position": 1, "text": "Iniciaría tratamiento de soporte, oxigenoterapia y ceftriaxona."}, {"position": 2, "text": "Iniciaría tratamiento con Trimetropim/sulfametoxazol, corticoides y oxigenoterapia."}, {"position": 3, "text": "Solicitaría serología del virus de la inmunodeficiencia humana."}, {"position": 4, "text": "Solicitaría estudio microbiológico de esputo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-193', '1b9d3c377eb30af4d4772bf7c1356162b5d3bd7b', 2025, 0, 193, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 46 años sufre accidente de tráfico a alta velocidad con varios vueltos del vehículo y necesidad de extricación por parte del equipo de bomberos. El paciente es trasladado en una UVI móvil al servicio de urgencias más próximo, con inmovilización en colchón de vacío. A su llegada al hospital se encuentra inestable a pesar de sueroterapia intensiva. A la exploración presenta los siguientes signos vitales: frecuencia respiratoria 35 rpm. Saturación de oxígeno 100% con mascarilla reservorio. Frecuencia cardíaca 140 lpm. Presión arterial 60/30 mm Hg. Temperatura 35,5ºC y glucemia 110 mg/dL. De las siguientes, indique la exploración o prueba complementaria clave del árbol de decisión en este paciente:', '[{"position": 1, "text": "Hemograma y bioquímica."}, {"position": 2, "text": "TC abdominal."}, {"position": 3, "text": "e-FAST (Extended Focused Abdominal Sonography for Trauma)."}, {"position": 4, "text": "Punción lavado peritoneal."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-194', 'fbcee7f4dbe995793b7ca58b62765e422cc4e735', 2025, 0, 194, false, false, 'Oncología', NULL, 'En un paciente diagnosticado de una lesión tumoral ósea maligna que ha recibido tratamiento neoadyuvante, se realiza resección de la pieza y posterior biopsia para su análisis anatomopatológico. Indique, de las siguientes, ¿cuál es la información más relevante para el pronóstico del paciente?:', '[{"position": 1, "text": "Tasa de necrosis en la pieza por efecto de terapia neoadyuvante."}, {"position": 2, "text": "Número de células tumorales en fase G0 de no división o interfase."}, {"position": 3, "text": "Porcentaje de células gigantes que se encuentran en la lesión."}, {"position": 4, "text": "Cantidad de células no estromales que componen el tumor."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-195', 'acab6c5338c95faf21e7479ddfaec6693c5ba7c2', 2025, 0, 195, false, false, 'Nefrología', NULL, 'Mujer de 60 años que acude al hospital por hematuria, mal estado general y fiebre. Se orienta clínicamente de insuficiencia renal progresiva y se decide realizarle una biopsia renal donde se observa una glomerulonefritis necrotizante con reacción extracapilar (semilunas) que afecta a más del 50% de los glomérulos. La inmunofluorescencia directa es negativa. Hay un dato del laboratorio de inmunología que nos ayudará a confirmar el diagnóstico, pero ¿cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Glomerulonefritis paucinimune."}, {"position": 2, "text": "Nefritis tubulointersticial."}, {"position": 3, "text": "Síndrome de Goodpasture."}, {"position": 4, "text": "Nefropatía IgA."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-196', 'c80c855e03c390bd272b06fb8b181cf483566eff', 2025, 0, 196, false, false, 'Pediatría', NULL, 'Niño de 3 años de edad con antecedentes de dermatitis atópica leve, sin alergias conocidas. Acude a la consulta con su madre quien comenta que en la última semana le han aparecido unas lesiones en la piel de la cara y la región glútea. Estas lesiones comenzaron como pequeñas máculas eritematosas que en pocos días pasaron a vesículas y erosiones superficiales cubiertas por costras amarillentas y que han ido aumentando en número y tamaño, extendiéndose rápidamente a la piel de alrededor. Ha estado rascándose las lesiones, lo que parece haberlas empeorado. También comenta que en la guardería hay otros niños que han presentado lesiones similares en la piel. El niño tiene buen estado general y no tiene fiebre, sólo se queja de picor en las lesiones. Ante este cuadro clínico, ¿cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Impétigo contagioso."}, {"position": 2, "text": "Molluscum contagioso."}, {"position": 3, "text": "Infección por herpes virus."}, {"position": 4, "text": "Candidiasis mucocutánea."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-197', '1f66482e9c00b9446adbe5efc927fa6266d10382', 2025, 0, 197, false, false, 'Dermatología', NULL, 'Hombre de 50 años que acude a la consulta por una lesión pigmentada en su pierna derecha que ha cambiado de tamaño y color en los últimos 4 meses. La lesión es de 8 mm de diámetro, asimétrica, con bordes irregulares y con varias tonalidades de marrón y negro. Además, refiere prurito ocasional en la zona. No tiene antecedentes personales de cáncer, ni otros de interés, pero su madre fue diagnosticada de melanoma a los 60 años. Se realiza una dermatoscopia que revela un patrón de red irregular, puntos negros, áreas de regresión y vasos sanguíneos irregulares. ¿Cuál es el manejo más apropiado?:', '[{"position": 1, "text": "Biopsia mediante punción de la parte más pigmentada de la lesión para confirmar el diagnóstico."}, {"position": 2, "text": "Biopsia mediante escisión completa con márgenes quirúrgicos de 2 mm y estudio histopatológico."}, {"position": 3, "text": "Monitorización de la lesión con dermatoscopia digital y seguimiento en 3 meses."}, {"position": 4, "text": "Terapia fotodinámica para reducir el tamaño de la lesión antes de realizar una biopsia."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-198', '29e0f0ef87b013829d07716664441dfbf9a8259d', 2025, 0, 198, false, false, 'Dermatología', NULL, 'Una lactante prematura de 32 semanas, consulta al mes de nacimiento por 3 hemangiomas infantiles superficiales que han crecido en las 2 últimas semanas en el antebrazo derecho, en el tórax y en la espalda. Respecto a los hemangiomas infantiles que presenta la paciente, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Tienen 3 fases evolutivas: una fase proliferativa en la que la lesión crece aceleradamente, un periodo de estabilidad y una fase involutiva."}, {"position": 2, "text": "Suponen la única lesión positiva para el marcador GLUT-1 (proteína transportadora de glucosa)."}, {"position": 3, "text": "Es necesario realizar estudios de imagen (la ecografía sería la técnica de elección) por el riesgo aumentado de hemangiomas a nivel visceral."}, {"position": 4, "text": "La mayoría de los hemangiomas infantiles tiene un curso clínico predecible por lo que, si no hay compromiso funcional ni estético, una opción válida es no tratar a estos pacientes."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-199', '288253b147efcf50a46996f00cb768d0dee8fec2', 2025, 0, 199, false, false, 'Dermatología', NULL, 'Hombre de 45 años con antecedentes personales de hipertensión arterial, dislipemia, hígado graso y esclerosis múltiple y en tratamiento con fingolimod, enalapril y sinvastatina, presenta una psoriasis con afectación de más del 10% de la superficie corporal y un índice de la severidad del área de psoriasis (PASI) de 14. Había realizado previamente tratamiento con activetina durante 15 meses con escasa mejoría. El paciente pregunta por otra alternativa terapéutica que consiga mejorar su psoriasis. ¿Cuál considera que es la mejor opción de tratamiento?:', '[{"position": 1, "text": "Fototerapia."}, {"position": 2, "text": "Biológico con mecanismo de acción anti-TNF (factor de necrosis tumoral)."}, {"position": 3, "text": "Ciclosporina."}, {"position": 4, "text": "Biológico con mecanismo de acción anti-Interleucina 23."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-200', '7eabab26ce722374927c15708141631dff9187e0', 2025, 0, 200, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Indique, de los siguientes, ¿cuál es un criterio de malignidad radiológica de los tumores óseos?:', '[{"position": 1, "text": "Esclerosis perilesional reactiva."}, {"position": 2, "text": "Presencia de calcificaciones puntiformes en el interior de la estructura ósea."}, {"position": 3, "text": "Rotura de la cortical ósea."}, {"position": 4, "text": "Localización epifisaria del tumor por la posibilidad de afectación de la articulación."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-201', '7d1bb52d6cda3fc0976635533489fbf84a4fd125', 2025, 0, 201, true, false, 'Enfermedades Infecciosas', NULL, 'En la enfermedad por arañazo de gato, señale la INCORRECTA:', '[{"position": 1, "text": "En los casos sin manifestaciones sistémicas de la enfermedad es suficiente con tratamiento tópico."}, {"position": 2, "text": "Para el diagnóstico es necesaria la práctica de una serología."}, {"position": 3, "text": "Si se precisa tratamiento antibiótico, se recomienda azitromicina 500 mg. en una dosis inicial y 250 mg cada 24 horas durante 4 días más."}, {"position": 4, "text": "La mayoría de los casos curan de forma espontánea en semanas o meses sin tratamiento de ningún tipo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-202', '4d20b59e639f3d03447de570f5640307794a3130', 2025, 0, 202, true, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 45 años que refiere desde hace 3 meses dolor en codo derecho irradiado a antebrazo, no asociado a parestesias ni sensación subjetiva de pérdida de fuerza. La intensidad del dolor va empeorando a lo largo del día, principalmente con trabajo de ordenador y con actividades deportivas. A la exploración física no se observan signos inflamatorios externos, presenta dolor a la palpación de epitróclea humeral y se reproduce su dolor al distender y resistir la musculatura flexora de antebrazo y mano. ¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Epicondilopatía medial."}, {"position": 2, "text": "Epicondilopatía lateral."}, {"position": 3, "text": "Síndrome compartimental crónico."}, {"position": 4, "text": "Neuropatía cubital por atrapamiento en canal epitrócleo-olecraniano."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-203', '6fe0515f8500cf34d008cc625540744e5e498292', 2025, 0, 203, true, false, 'Oncología', NULL, 'Hombre de 70 años con un PSA de 13 ng/mL y tacto rectal pétreo. El estudio diagnóstico revela cáncer de próstata de alto riesgo, Gleason 9, metastásico, con afectación ósea (más de 8 lesiones en el esqueleto axial) y metástasis hepáticas. ¿Cuál de los siguientes es el tratamiento inicial indicado en la actualidad?:', '[{"position": 1, "text": "Prostatectomía radical con linfadenectomía extendida y resección de las metástasis."}, {"position": 2, "text": "Radioterapia externa pélvica y radioterapia estereotáxica de las metástasis."}, {"position": 3, "text": "Braquiterapia pélvica de alta tasa."}, {"position": 4, "text": "Antiandrógenos inicialmente más análogos de la LHRH + enzalutamida + docetaxel."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-204', '7b6d1d544a69517531eaaeaa63c405b2e49f8a3a', 2025, 0, 204, true, false, 'Ginecología y Obstetricia', NULL, 'Gestante de 36 años primigesta sin factores de riesgo excepto índice de masa corporal de 32 pregestacional, que acude a urgencias a las 28 semanas y presenta una rotura prematura de membranas. En el momento del ingreso la analítica es normal, no presenta dinámica uterina y la longitud cervical es de 38 mm. ¿Cuál de las siguientes afirmaciones es INCORRECTA?', '[{"position": 1, "text": "Iniciaremos maduración pulmonar fetal con corticoides."}, {"position": 2, "text": "Se realizará profilaxis de corioamnionitis mediante antibioterapia endovenosa."}, {"position": 3, "text": "Se iniciará neuroprotección fetal."}, {"position": 4, "text": "Se iniciará profilaxis tromboembólica con heparina de bajo peso molecular."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-205', '7569c84eebafec82cc67497bc3ef9e539d6617bc', 2025, 0, 205, true, false, 'Reumatología', NULL, '¿Qué autoanticuerpos en las miopatías inflamatorias debería alertarnos de un curso agresivo de una neumonía intersticial asociada?:', '[{"position": 1, "text": "Anti-TIF-1."}, {"position": 2, "text": "Anti MDA-5."}, {"position": 3, "text": "Anti-Mi2."}, {"position": 4, "text": "Anti-PM/SCL."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-206', 'ae8716f53ce3b0d33596d613ccd3f9581700b54b', 2025, 0, 206, true, false, 'Pediatría', NULL, 'Avisan de paritorio por recién nacido pretérmino tardío (35+3 semanas de edad gestacional) sin otros factores de riesgo. Al nacimiento no presenta esfuerzo respiratorio y se decide monitorización con pulsioximetría. No inicia esfuerzo por lo que a los 30 segundos se ventila con presión positiva intermitente (VPPI) (presión inspiratoria 20 cm H20 y PEEP 6 cm H20 y FiO2 0,21) durante 1 minuto. Inicia llanto y esfuerzo respiratorio pero con signos de dificultad respiratoria en torno a los 3 minutos de vida con cianosis asociada. En la monitorización presenta frecuencia cardíaca de 170 lpm y Sat O2 del 75%. ¿Cuál es su actuación en este momento?:', '[{"position": 1, "text": "Retirar soporte respiratorio y aumento aporte de oxígeno."}, {"position": 2, "text": "Mantener VPPI y fracción inspirada de oxígeno al 21%."}, {"position": 3, "text": "Pasar a modalidad presión positiva continua y aumento aporte de oxígeno."}, {"position": 4, "text": "Pasar a modalidad presión positiva continua y fracción inspirada de oxígeno al 21%."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-207', 'e93a51f745f512ccd7b73ffad79fc5e9f2d3ad38', 2025, 0, 207, true, false, 'Medicina Preventiva y Epidemiología', NULL, 'En relación con el estudio de la causalidad en epidemiología, solo uno de los siguientes es un criterio o consideración causal de Bradford Hill. Señálelo:', '[{"position": 1, "text": "Gradiente biológico (relación dosis-respuesta)."}, {"position": 2, "text": "Ausencia de sesgos."}, {"position": 3, "text": "Ausencia de confusión."}, {"position": 4, "text": "Significación estadística de la asociación."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-208', '2f106cacfe0366721b3f068c341f676124959082', 2025, 0, 208, true, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 80 años con antecedentes de hipertensión arterial y diabetes mellitus, así como un accidente isquémico cerebral transitorio 2 años antes. Hospitalizado actualmente tras presentar un infarto de miocardio sin elevación del segmento ST (IAMSEST). En la coronariografía se observa enfermedad arterial coronaria multivaso no revascularizable. En la analítica la función renal es normal, sin anemia. ¿Cuál es el tratamiento antiagregante que debiera recomendarse como primera opción?:', '[{"position": 1, "text": "Ácido acetil salicílico 100 mg/día de forma indefinida."}, {"position": 2, "text": "Ácido acetil salicílico 100 mg/día de forma indefinida y clopidogrel 75 mg/día durante 1 año."}, {"position": 3, "text": "Ácido acetil salicílico 100 mg/día de forma indefinida y ticagrelor 90 mg/día durante 1 año."}, {"position": 4, "text": "Ácido acetil salicílico 100 mg/día de forma indefinida y prasugrel 5 mg/día durante 1 año."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-209', '92862165cd90800dfc3a1add99e97b19e629d295', 2025, 0, 209, true, false, 'Aparato Digestivo', NULL, 'Hombre de 34 años con poliposis intestinal y manifestaciones extraintestinales como hipertrofia congénita de retina y osteomas mandibulares. Para hacer el diagnóstico genético se debe analizar el gen:', '[{"position": 1, "text": "Gen MYH."}, {"position": 2, "text": "Gen PTEN."}, {"position": 3, "text": "Gen APC."}, {"position": 4, "text": "Gen p53."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-210', 'e7070eeb302ced72862f0c29fe22a3d0e8ea4d53', 2025, 0, 210, true, false, 'Psiquiatría', NULL, 'Acude por primera vez a la consulta una paciente de 17 años con anorexia nerviosa de un año de evolución. En la exploración física y analítica son característicos los siguientes signos EXCEPTO:', '[{"position": 1, "text": "Lanugo."}, {"position": 2, "text": "Taquicardia."}, {"position": 3, "text": "Hipopotasemia si existen conductas purgativas como los vómitos o el uso de laxantes."}, {"position": 4, "text": "Disminución de hormonas gonadotróficas."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-001', 'ddeb5bbcd44d62d1dcbac2b686df1b0c00a1ab7f', 2026, 0, 1, false, false, NULL, NULL, 'En un adolescente de 17 años con dolor de rodilla de tres meses de evolución, antecedente de traumatismo leve y esta radiografía, ¿cuál de las siguientes entidades debe considerarse en el diagnóstico diferencial según la clínica y la imagen radiográfica (IMAGEN 1)?:', '[{"position": 1, "text": "Osteosarcoma."}, {"position": 2, "text": "Osteomielitis subaguda."}, {"position": 3, "text": "Osteocondritis disecante."}, {"position": 4, "text": "Tumor de células gigantes."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/26/image_1.jpeg', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-002', 'f0d965c7324d77941fe8c3a4a516ebe8de503180', 2026, 0, 2, false, false, NULL, NULL, '¿Cuál de los siguientes hallazgos radiográficos es más útil para diferenciar osteosarcoma de otras causas de dolor crónico de rodilla en adolescentes (IMAGEN 2)?:', '[{"position": 1, "text": "Lesión lítica con bordes bien definidos y sin reacción periostal."}, {"position": 2, "text": "Lesión con patrón mixto lítico-esclerótico y reacción periostal tipo triangulo de Codman."}, {"position": 3, "text": "Lesión subcondral con colapso de la placa ósea."}, {"position": 4, "text": "Lesión con calcificaciones puntiformes y sin masa de partes blandas."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/26/image_2.jpeg', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-003', '4a83b0b7b96d4b3a7def1d9e87a0784babf3c0d4', 2026, 0, 3, false, false, NULL, NULL, 'Ingresa una paciente de 83 años para tratamiento de aneurisma de aorta abdominal de 50mm de diámetro, por crecimiento rápido en los últimos 6 meses. Entre sus antecedentes destaca: hipertensión arterial, dislipemia, portadora de marcapasos por bloqueo auriculo-ventricular completo como antecedentes. Veinticuatro horas tras la cirugía la paciente presenta distensión, dolor abdominal y rectorragias, acompañado de leucocitosis 32.100μl, con el 95% de neutrófilos y 278 de LDH como únicas alteraciones analíticas, por lo que se realiza un angio-tomografia computerizada, con la siguiente imagen (IMAGEN 3). ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Isquemia mesentérica aguda."}, {"position": 2, "text": "Isquemia mesentérica crónica."}, {"position": 3, "text": "Isquemia mesentérica no oclusiva."}, {"position": 4, "text": "Colitis Isquémica."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/26/image_3.jpeg', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-004', 'ca2b35bb7ec998f794dd6553db0080d4adbfcf37', 2026, 0, 4, false, false, NULL, NULL, 'Colitis isquémica.
